from lexer import Lexer, ParseError

# AST nodes are tuples; first element is kind string, second is line int.

class FunctionProto:
    __slots__=("params","is_vararg","body","line","lastline","chunk","source","name_hint","upvalue_names","local_names","source_slice")
    def __init__(self, params, is_vararg, body, line, lastline, chunk):
        self.params=params  # list of bytes names
        self.is_vararg=is_vararg
        self.body=body  # block node
        self.line=line
        self.lastline=lastline
        self.chunk=chunk  # ChunkInfo
        self.source=None
        self.name_hint=None
        self.upvalue_names=None
        self.local_names=None
        self.source_slice=None

class ChunkInfo:
    __slots__=("display","raw","source_bytes")
    def __init__(self, display, raw=None, source_bytes=None):
        self.display=display  # bytes display in errors
        self.raw=raw if raw is not None else display
        self.source_bytes=source_bytes

def make_chunk_display(chunkname_bytes, source_bytes=None):
    # Lua chunkid rules approximate (LUA_IDSIZE 60)
    if chunkname_bytes is None:
        # default from source
        if source_bytes is None:
            return b"[?]"
        chunkname_bytes = source_bytes
    cs = chunkname_bytes
    IDSIZE=60
    if cs[:1]==b"@":
        name=cs[1:]
        if len(name) < IDSIZE:
            return name
        else:
            # ellide beginning
            return b"..." + name[-(IDSIZE-4):]  # "@..."? Lua: ... + last part, no @? check lobject luaO_chunkid: if '@' and too long -> "..."?? approx
    if cs[:1]==b"=":
        name=cs[1:]
        if len(name) < IDSIZE:
            return name
        else:
            return name[:IDSIZE-1]
    # plain string source as name: [string "..."]
    # Find first newline
    # Lua: if first line fits, [string "line"], else trimmed with ... and also shows ...?
    first = cs.split(b"\n")[0].split(b"\r")[0]
    # add ... if source has newline or too long?
    has_nl = (b"\n" in cs or b"\r" in cs)
    # buffersize: [string "..."] length
    # Simplified correct for common short cases
    prefix=b'[string "'
    suffix=b'"]'
    avail=IDSIZE - len(prefix) - len(suffix) - (3 if has_nl else 0)
    if len(first) > avail:
        first=first[:avail]
        return prefix+first+b"..."+suffix
    else:
        if has_nl:
            return prefix+first+b"..."+suffix
        else:
            return prefix+first+suffix

