    b"^":(10,9),
}
UNARY_PRI=8

class Parser:
    def __init__(self, source_bytes, chunk_display, chunk_info):
        self.lex = Lexer(source_bytes, chunk_display)
        self.chunk = chunk_info
        self.func_depth = 0
        self.loop_depth_stack = []  # per function loop context? Simple count reset in function
        self.loop_depth = 0
        # goto handling: stack of blocks info dicts per function? We'll maintain list parsing blocks.
        # Each block context: dict with 'labels': {}, 'gotos': [], 'locals_count_snapshot' (?) -- approximate validation at end of block/function
        self.block_stack = []  # list of contexts
        self.function_block_stack = []  # save block_stack

    # helpers
    @property
    def cur(self):
        return self.lex.current
    def curtype(self):
        return self.lex.current.type
    def advance(self):
        return self.lex.next_token()
    def error_expected(self, expected_bytes, near_tok=None):
        tok = near_tok or self.cur
        # message: 'X' expected near 'Y'
        raise ParseError(b"'"+expected_bytes+b"' expected near '"+tok.display()+b"'", tok.line)
    def error_expected_close(self, expected_bytes, open_name_bytes, open_line, near_tok=None):
        tok = near_tok or self.cur
        if tok.line != open_line and False:
            pass
        raise ParseError(b"'"+expected_bytes+b"' expected (to close '"+open_name_bytes+b"' at line "+str(open_line).encode()+b") near '"+tok.display()+b"'", tok.line)
    def error_unexpected(self, tok=None, msg_prefix=b""):
        tok = tok or self.cur
        raise ParseError(b"unexpected symbol near '"+tok.display()+b"'", tok.line)
    def check_match(self, expected, open_word, open_line):
        if self.curtype() != expected:
            # if same line? Lua's check_match always includes "(to close ...)" if token is ...? Original: for ')' expected near '<eof>' earlier even though '(' line 2 same? It showed just ')' expected near '<eof>' no to close. Hmm Lua check_match uses error_expected with to close if line diff? Actually lparser: if !match then if line== token line (?) error_expected else error with to close.
            if self.cur.line == open_line:
                self.error_expected(expected)
            else:
                self.error_expected_close(expected, open_word, open_line)
        self.advance()
    def expect(self, typ):
        if self.curtype() != typ:
            self.error_expected(typ if typ!=b"<name>" else b"<name>")
        return self.advance()
    def expect_name(self):
        if self.curtype() != b"<name>":
            self.error_expected(b"<name>")
        tok=self.advance()
        return tok.value  # bytes
    def test_next(self, typ):
        if self.curtype()==typ:
            self.advance(); return True
        return False

    # Entry
    def parse_chunk(self):
        # main function: vararg, no params
        line=1
        self._enter_function()
        body = self.parse_block()
        # after block, expect EOF
        if self.curtype() != b"<eof>":
            # block parser would have stopped on end etc: generate appropriate?
            # If stray 'end', Lua: 'end' expected? Wait at chunk level unexpected? Prob: <eof> expected near 'end' ? Check later. Use that.
            raise ParseError(b"<eof> expected near '"+self.cur.display()+b"'", self.cur.line)
        self._leave_function()
        proto = FunctionProto([], True, body, 0, 0, self.chunk)
        proto.name_hint=None
        return proto

    def _enter_function(self):
        self.function_block_stack.append((self.block_stack, self.loop_depth))
        self.block_stack=[]
        self.loop_depth=0
        self.func_depth+=1
    def _leave_function(self):
        # validate unresolved gotos in remaining? parse_block already validates at block exit.
        self.block_stack, self.loop_depth = self.function_block_stack.pop()
        self.func_depth-=1

    # Block context for goto/label
    def _push_block(self, is_loop=False):
        ctx={'labels':{}, 'gotos':[], 'is_loop':is_loop, 'locals':[]}
        self.block_stack.append(ctx)
        return ctx
    def _pop_block(self):
        ctx=self.block_stack.pop()
        # Validate gotos in this block that aim labels defined in this block: if goto targets label not defined in this or outer block, future outer may define. Lua labels visible in whole block they appear and inner blocks so unresolved at end of entire function maybe.
        # We defer: pass unresolved gotos to parent context? But a goto in inner block can jump to label in outer. So propagate gotos whose label not in this block.
        pending=[]
        for gname, gline in ctx['gotos']:
            if gname not in ctx['labels']:
                pending.append((gname,gline))
        if self.block_stack:
            # add to parent's gotos for resolution check later (but distinguish origin? Keep)
            self.block_stack[-1]['gotos'].extend(pending)
        else:
            # outermost block of function: any pending undefined
            if pending:
                gname,gline=pending[0]
                raise ParseError(b"undefined label '"+gname+b"'", gline)
        return ctx

    def parse_block(self, is_loop=False):
        # Returns block node tuple ('block', line, [stmts])
        line=self.cur.line
        ctx=self._push_block(is_loop=is_loop)
        stmts=[]
        # block follow logic
        while self.curtype() not in BLOCK_FOLLOW:
            # last statements return/break handled specially inside parse_statement but need stop.
            if self.curtype() == b"return":
                stmt=self.parse_return()
                stmts.append(stmt)
                # optional semicolon already in parse_return
                break
            if self.curtype() == b"break":
                stmt_line=self.cur.line
                self.advance()
                # break validation: must be in loop
                # self.loop_depth tracked
                if self.loop_depth==0:
                    # Lua error: no loop to break? Actual message LT: (?) "break outside loop" ??? in LuaJIT: parse error? Probe later.
                    raise ParseError(b"no loop to break near 'break'", stmt_line)
                stmts.append(('break', stmt_line))
                # optional semi
                self.test_next(b';')
                break
            stmt=self.parse_statement()
            if stmt is not None:
                # parse_statement may return list for labels? We'll make label stmt
                if isinstance(stmt, list):
                    stmts.extend(stmt)
                else:
                    stmts.append(stmt)
            # optional semicolon separator after each statement
            self.test_next(b';')
            # continue loop
        # Validate pop block
        # Record labels positions with stmt index: ctx labels dict name->stmt index (set when parse label, index needs position in stmts at that time; we update during parse_statement via closure? parser_context store current block stmts ref)
        # Simpler: after building stmts, scan for label stmts to build map
        labels={}
        for idx,st in enumerate(stmts):
            if st[0]=='label':
                labels[st[2]]=idx
        ctx_labels = labels  # used for validation: overwrite
        ctx['labels']=labels
        self._pop_block()
        return ('block', line, stmts, labels)

    def parse_return(self):
        line=self.cur.line
        self.advance() # return
        exprs=[]
        # return may be followed by exprlist if not blockfollow or ';'
        if self.curtype() not in BLOCK_FOLLOW and self.curtype() != b';':
            exprs=self.parse_exprlist()
        self.test_next(b';')
        return ('return', line, exprs)

    def parse_statement(self):
        t=self.curtype()
        line=self.cur.line
        if t==b"do":
            self.advance()
            blk=self.parse_block()
            self.check_match(b"end", b"do", line)
            return ('do', line, blk)
        elif t==b"while":
            self.advance()
            cond=self.parse_expr()
            if self.curtype()!=b"do":
                self.error_expected(b"do")
            self.advance()
            self.loop_depth+=1
            blk=self.parse_block(is_loop=True)
            self.loop_depth-=1
            self.check_match(b"end", b"while", line)
            return ('while', line, cond, blk)
        elif t==b"repeat":
            self.advance()
            self.loop_depth+=1
            blk=self.parse_block(is_loop=True)
            self.loop_depth-=1
            if self.curtype()!=b"until":
                self.error_expected_close(b"until", b"repeat", line) if self.cur.line!=line else self.error_expected(b"until")
            self.advance()
            # until condition expr is parsed; scope includes block locals (runtime env handling)
            cond=self.parse_expr()
            return ('repeat', line, blk, cond)
        elif t==b"if":
            return self.parse_if()
        elif t==b"for":
            return self.parse_for()
        elif t==b"function":
            self.advance()
            # function name funcname: Name { '.' Name } [ ':' Name ]
            base_line=self.cur.line
            name=self.expect_name()
            # build target expression node
            target=('var', base_line, name)
            is_method=False
            while self.curtype()==b".":
                self.advance()
                fname_line=self.cur.line
                fname=self.expect_name()
                target=('index', fname_line, target, ('string', fname_line, fname))
            if self.curtype()==b":":
                self.advance()
                fname_line=self.cur.line
                fname=self.expect_name()
                target=('index', fname_line, target, ('string', fname_line, fname))
                is_method=True
            func_expr=self.parse_function_body(is_method=is_method)
            # name hint for function proto
            return ('assign', line, [target], [func_expr])
        elif t==b"local":
            self.advance()
            if self.curtype()==b"function":
                self.advance()
                fname_line=self.cur.line
                fname=self.expect_name()
                func_expr=self.parse_function_body(is_method=False)
                return ('localfunc', line, fname, func_expr)
            else:
                # local namelist ['=' explist]
                names=[]
                while True:
                    n=self.expect_name()
                    names.append(n)
                    if not self.test_next(b','):
                        break
                exprs=[]
                if self.test_next(b'='):
                    exprs=self.parse_exprlist()
                return ('local', line, names, exprs)
        elif t==b"::":
            # label
            self.advance()
            lname=self.expect_name()
            if self.curtype()!=b"::":
                self.error_expected(b"::")
            self.advance()
            # duplicate label check in current block (basic)
            if self.block_stack:
                # labels are scanned later; but temporary detection store in ctx dict 'seen labels'
                ctx=self.block_stack[-1]
                seen=ctx.get('seen_labels')
                if seen is None:
                    ctx['seen_labels']=seen={}
                if lname in seen:
                    raise ParseError(b"label '"+lname+b"' already defined at line "+str(seen[lname]).encode(), line)
                seen[lname]=line
            return ('label', line, lname)
        elif t==b"<name>" and self.cur.value==b"goto":
            # lookahead second token is name -> goto statement
            nxt=self.lex.lookahead()
            if nxt.type==b"<name>":
                self.advance() # goto
                gline=self.cur.line
                gname=self.expect_name()
                if self.block_stack:
                    self.block_stack[-1]['gotos'].append((gname,gline))
                return ('goto', line, gname)
            else:
                return self.parse_expr_statement()
        else:
            return self.parse_expr_statement()

    def parse_if(self):
        line=self.cur.line
        clauses=[]
        self.advance() # if
        cond=self.parse_expr()
        if self.curtype()!=b"then":
            self.error_expected(b"then")
        self.advance()
        blk=self.parse_block()
        clauses.append((cond,blk,line))
        while self.curtype()==b"elseif":
            eline=self.cur.line
            self.advance()
            cond=self.parse_expr()
            if self.curtype()!=b"then":
                self.error_expected(b"then")
            self.advance()
            blk=self.parse_block()
            clauses.append((cond,blk,eline))
        else_blk=None
        if self.curtype()==b"else":
            self.advance()
            else_blk=self.parse_block()
        self.check_match(b"end", b"if", line)
        return ('if', line, clauses, else_blk)

    def parse_for(self):
        line=self.cur.line
        self.advance() # for
        name_line=self.cur.line
        first_name=self.expect_name()
        if self.curtype()==b"=":
            # numeric for
            self.advance()
            start_expr=self.parse_expr()
            if self.curtype()!=b',':
                self.error_expected(b",")
            self.advance()
            limit_expr=self.parse_expr()
            step_expr=None
            if self.test_next(b','):
                step_expr=self.parse_expr()
            if self.curtype()!=b"do":
                self.error_expected(b"do")
            self.advance()
            self.loop_depth+=1
            blk=self.parse_block(is_loop=True)
            self.loop_depth-=1
            self.check_match(b"end", b"for", line)
            return ('fornum', line, first_name, start_expr, limit_expr, step_expr, blk)
        elif self.curtype()==b',' or self.curtype()==b"in":
            names=[first_name]
            while self.test_next(b','):
                names.append(self.expect_name())
            if self.curtype()!=b"in":
                # Lua error: 'in' expected or '='? The generic for uses... if first token after name not = or ,/in parser error '=' expected? Actually for statement in lparser: switch next token: '=' numeric, ',' / 'in' generic, default error "'=' or 'in' expected"? probe later.
                self.error_expected(b"in")
            self.advance()
            exprs=self.parse_exprlist()
            if self.curtype()!=b"do":
                self.error_expected(b"do")
            self.advance()
            self.loop_depth+=1
            blk=self.parse_block(is_loop=True)
            self.loop_depth-=1
            self.check_match(b"end", b"for", line)
            return ('forgen', line, names, exprs, blk)
        else:
            # error: '=' or 'in' expected near ?
            raise ParseError(b"'=' or 'in' expected near '"+self.cur.display()+b"'", self.cur.line)

    def parse_expr_statement(self):
        # suffixed expr ; if call stmt, else assignment
        line=self.cur.line
        expr=self.parse_suffixed_expr()
        if expr[0] in ('call','methodcall'):
            return ('callstmt', line, expr)
        # assignment: var list
        targets=[expr]
        while self.test_next(b','):
            e=self.parse_suffixed_expr()
            if e[0] in ('call','methodcall'):
                # Lua: syntax error? "syntax error near ..." (?) probe later
                raise ParseError(b"syntax error near '"+self.cur.display()+b"'", self.cur.line)
            targets.append(e)
        if self.curtype()!=b"=":
            self.error_expected(b"=")
        self.advance()
        exprs=self.parse_exprlist()
        return ('assign', line, targets, exprs)

    # Expressions
    def parse_exprlist(self):
        exprs=[self.parse_expr()]
        while self.test_next(b','):
            exprs.append(self.parse_expr())
        return exprs
    def parse_expr(self):
        return self.parse_subexpr(0)

    def parse_subexpr(self, limit):
        line=self.cur.line
        t=self.curtype()
        if t in (b"not", b"-", b"#"):
            op=t; self.advance()
            operand=self.parse_subexpr(UNARY_PRI)
            left=('unop', line, op, operand)
        else:
            left=self.parse_simple_expr()
        while True:
            op=self.curtype()
            if op not in BINOP_PRI:
                break
            lpri, rpri = BINOP_PRI[op]
            if lpri <= limit:
                break
            opline=self.cur.line
            self.advance()
            # and/or special node but still binop
            right=self.parse_subexpr(rpri)
            left=('binop', opline, op, left, right)
        return left

    def parse_simple_expr(self):
        t=self.curtype(); line=self.cur.line
        if t==b"<number>":
            tok=self.advance()
            val=tok.value
            if isinstance(val, tuple) and val and val[0]=="suffix":
                return ('cdata_num', line, val)  # suffix tuple
            return ('number', line, float(val))
        elif t==b"<string>":
            tok=self.advance()
            return ('string', line, tok.value)
        elif t==b"nil":
            self.advance(); return ('nil', line)
        elif t==b"true":
            self.advance(); return ('bool', line, True)
        elif t==b"false":
            self.advance(); return ('bool', line, False)
        elif t==b"...":
            self.advance(); return ('vararg', line)
        elif t==b"function":
            self.advance()
            return self.parse_function_body(is_method=False)
        elif t==b"{":
            return self.parse_table_constructor()
        else:
            return self.parse_suffixed_expr()

    def parse_suffixed_expr(self):
        # primary exp
        line=self.cur.line; t=self.curtype()
        if t==b"(":
            self.advance()
            inner=self.parse_expr()
            # check match ')'
            self.check_match(b")", b"(", line)
            expr=('paren', line, inner)
        elif t==b"<name>":
            name=self.advance().value
            expr=('var', line, name)
        else:
            self.error_unexpected()
        # suffixes
        while True:
            line2=self.cur.line; tt=self.curtype()
            if tt==b".":
                self.advance()
                fname=self.expect_name()
                expr=('index', line2, expr, ('string', line2, fname))
            elif tt==b"[":
                self.advance()
                k=self.parse_expr()
                self.check_match(b"]", b"[", line2)
                expr=('index', line2, expr, k)
            elif tt==b":":
                self.advance()
                mname_line=self.cur.line
                mname=self.expect_name()
                args=self.parse_function_args()
                # methodcall node: ('methodcall', line, obj_expr, method_name, args list or special)
                expr=('methodcall', mname_line, expr, mname, args)
            elif tt in (b"(", b"{", b"<string>"):
                args=self.parse_function_args()
                expr=('call', line2, expr, args)
            else:
                break
        return expr

    def parse_function_args(self):
        # returns ('args', list) or ('arg_single', expr)?? We'll return list of exprs or marker tuples: list nodes already.
        line=self.cur.line; t=self.curtype()
        if t==b"(":
            self.advance()
            if self.curtype()==b")":
                args=[]
            else:
                args=self.parse_exprlist()
            self.check_match(b")", b"(", line)
            return args
        elif t==b"{":
            tc=self.parse_table_constructor()
            return [tc]
        elif t==b"<string>":
            tok=self.advance()
            return [('string', line, tok.value)]
        else:
            # function arguments expected near X
            raise ParseError(b"function arguments expected near '"+self.cur.display()+b"'", self.cur.line)

    def parse_table_constructor(self):
        line=self.cur.line
        self.expect(b"{")
        fields=[]
        while self.curtype()!=b"}":
            fline=self.cur.line
            if self.curtype()==b"[":
                self.advance()
                k=self.parse_expr()
                self.check_match(b"]", b"[", fline)
                if self.curtype()!=b"=":
                    self.error_expected(b"=")
                self.advance()
                v=self.parse_expr()
                fields.append(('key', fline, k, v))
            elif self.curtype()==b"<name>":
                # lookahead if next '='
                nxt=self.lex.lookahead()
                if nxt.type==b"=":
                    name=self.advance().value
                    self.advance() # =
                    v=self.parse_expr()
                    fields.append(('namekey', fline, name, v))
                else:
                    v=self.parse_expr()
                    fields.append(('list', fline, v))
            else:
                v=self.parse_expr()
                fields.append(('list', fline, v))
            if self.curtype() in (b',', b';'):
                self.advance()
                continue
            elif self.curtype()==b"}":
                break
            else:
                # error: '}' expected or ',' expected? Lua: error " '}' expected near ..." or " ',' expected ..."? Actually constructor: `check_match '}'`; so if separator missing next field causes (?) parser loops and expects `,` or `;`? We'll produce "}" expected?
                # Based on lparser recfield etc: After field, if not separator... movement.
                raise ParseError(b"'}' expected near '"+self.cur.display()+b"'", self.cur.line)
        self.check_match(b"}", b"{", line)
        return ('table', line, fields)

    def parse_function_body(self, is_method=False):
        # cur tok is '(' expected
        line=self.cur.line  # line of '(' or function? Function defined line in debug is line of 'function' keyword? For anonymous expressions, linedefined is line where function starts (? token function). But our caller advanced 'function'. We'll use current line approximation: if paren same line usually ok. Parser could be improved by passing func line.
        # To capture function line better, function statements/expr callers could set self.. Keep.
        if self.curtype()!=b"(":
            self.error_expected(b"(")
        paren_line=self.cur.line
        self.advance()
        params=[]
        if is_method:
            params.append(b"self")
        is_vararg=False
        if self.curtype()!=b")":
            while True:
                if self.curtype()==b"<name>":
                    params.append(self.advance().value)
                elif self.curtype()==b"...":
                    self.advance(); is_vararg=True
                    break
                else:
                    raise ParseError(b"<name> or '...' expected near '"+self.cur.display()+b"'", self.cur.line)
                if not self.test_next(b','):
                    break
                # after comma, if ... next loop handles
        self.check_match(b")", b"(", paren_line)
        # body block is a new function
        self._enter_function()
        body=self.parse_block()
        lastline=self.cur.line
        # check end
        self.check_match(b"end", b"function", line)
        self._leave_function()
        proto=FunctionProto(params, is_vararg, body, line, lastline, self.chunk)
        return ('function', line, proto)

