        elif t==b"<name>" and self.cur.value==b"goto":
            # lookahead second token is name -> goto statement
            nxt=self.lex.lookahead()
            if nxt.type==b"<name>":
                self.advance() # goto
                gline=self.cur.line
                gname=self.expect_name()
                if self.block_stack:
                    self.block_stack[-1]['gotos'].append((gname,gline))
                return ('goto', line, gname)
            else:
                return self.parse_expr_statement()
        else:
            return self.parse_expr_statement()

    def parse_if(self):
        line=self.cur.line
        clauses=[]
        self.advance() # if
        cond=self.parse_expr()
        if self.curtype()!=b"then":
            self.error_expected(b"then")
        self.advance()
        blk=self.parse_block()
        clauses.append((cond,blk,line))
        while self.curtype()==b"elseif":
            eline=self.cur.line
            self.advance()
            cond=self.parse_expr()
            if self.curtype()!=b"then":
                self.error_expected(b"then")
            self.advance()
            blk=self.parse_block()
            clauses.append((cond,blk,eline))
        else_blk=None
        if self.curtype()==b"else":
            self.advance()
            else_blk=self.parse_block()
        self.check_match(b"end", b"if", line)
        return ('if', line, clauses, else_blk)

    def parse_for(self):
        line=self.cur.line
        self.advance() # for
        name_line=self.cur.line
        first_name=self.expect_name()
        if self.curtype()==b"=":
            # numeric for
            self.advance()
            start_expr=self.parse_expr()
            if self.curtype()!=b',':
                self.error_expected(b",")
            self.advance()
            limit_expr=self.parse_expr()
            step_expr=None
            if self.test_next(b','):
                step_expr=self.parse_expr()
            if self.curtype()!=b"do":
                self.error_expected(b"do")
            self.advance()
            self.loop_depth+=1
            blk=self.parse_block(is_loop=True)
            self.loop_depth-=1
            self.check_match(b"end", b"for", line)
            return ('fornum', line, first_name, start_expr, limit_expr, step_expr, blk)
        elif self.curtype()==b',' or self.curtype()==b"in":
            names=[first_name]
            while self.test_next(b','):
                names.append(self.expect_name())
            if self.curtype()!=b"in":
                # Lua error: 'in' expected or '='? The generic for uses... if first token after name not = or ,/in parser error '=' expected? Actually for statement in lparser: switch next token: '=' numeric, ',' / 'in' generic, default error "'=' or 'in' expected"? probe later.
                self.error_expected(b"in")
            self.advance()
            exprs=self.parse_exprlist()
            if self.curtype()!=b"do":
                self.error_expected(b"do")
            self.advance()
            self.loop_depth+=1
            blk=self.parse_block(is_loop=True)
            self.loop_depth-=1
