    def parse_expr_statement(self):
        # suffixed expr ; if call stmt, else assignment
        line=self.cur.line
        expr=self.parse_suffixed_expr()
        if expr[0] in ('call','methodcall'):
            return ('callstmt', line, expr)
        # assignment: var list
        targets=[expr]
        while self.test_next(b','):
            e=self.parse_suffixed_expr()
            if e[0] in ('call','methodcall'):
