                raise ParseError(b"'}' expected near '"+self.cur.display()+b"'", self.cur.line)
        self.check_match(b"}", b"{", line)
        return ('table', line, fields)

    def parse_function_body(self, is_method=False):
        # cur tok is '(' expected
        line=self.cur.line  # line of '(' or function? Function defined line in debug is line of 'function' keyword? For anonymous expressions, linedefined is line where function starts (? token function). But our caller advanced 'function'. We'll use current line approximation: if paren same line usually ok. Parser could be improved by passing func line.
        # To capture function line better, function statements/expr callers could set self.. Keep.
        if self.curtype()!=b"(":
            self.error_expected(b"(")
        paren_line=self.cur.line
        self.advance()
        params=[]
        if is_method:
            params.append(b"self")
        is_vararg=False
        if self.curtype()!=b")":
            while True:
                if self.curtype()==b"<name>":
                    params.append(self.advance().value)
                elif self.curtype()==b"...":
                    self.advance(); is_vararg=True
                    break
                else:
                    raise ParseError(b"<name> or '...' expected near '"+self.cur.display()+b"'", self.cur.line)
                if not self.test_next(b','):
                    break
