        self.check_match(b")", b"(", paren_line)
        # body block is a new function
        self._enter_function()
        body=self.parse_block()
        lastline=self.cur.line
        # check end
        self.check_match(b"end", b"function", line)
        self._leave_function()
        proto=FunctionProto(params, is_vararg, body, line, lastline, self.chunk)
        return ('function', line, proto)

