class CallInfo:
    __slots__=("func","name","namewhat","line","is_lua","proto","chunk_display","env","varargs","args","what","active_locals","tail_calls","fenv","is_main_chunk","called_from_c")
    def __init__(self, func, name=None, namewhat=b"", line=0, is_lua=False, proto=None):
        self.func = func
        self.name = name
        self.namewhat = namewhat
        self.line = line
        self.is_lua = is_lua
        self.proto = proto
        self.chunk_display = proto.chunk.display if proto else b"[C]"
        self.env = None
        self.varargs = []
        self.args = []
        self.what = b"Lua" if is_lua else b"C"
        self.active_locals = []
        self.tail_calls = 0
        self.fenv = None
        self.is_main_chunk = False
        self.called_from_c = False

class LuaState:
    def __init__(self):
        self.globals = LuaTable()
        self.registry = LuaTable()
        self.main_thread = LuaThread(self, None, main=True)
        self.thread_map = {}  # py thread ident -> LuaThread
        self._thread_lock = threading.Lock()
        self.type_metatables = {}  # bytes typ->table or None
        self.string_mt = LuaTable()
        self.type_metatables[b"string"] = self.string_mt
        self.progname = b"luajit"
        self.jit_on = True
        self.jit_flags = {b"fold",b"cse",b"dce",b"fwd",b"dse",b"narrow",b"loop",b"abc",b"sink",b"fuse"}
        self.jit_params = {}
        self.exit_code = None
        self.current_error_snapshot = None
        self.hooks = {}  # LuaThread id -> (func,mask,count, counter)
        self.cdata_index_handler = None
        self.cdata_newindex_handler = None
        self.cdata_call_handler = None
        self.cdata_len_handler = None
        self.cdata_tostring_handler = None
        self.cdata_arith_handler = None
        self.gc_count_kb = 100
        # default io handles set by stdlib
        self.io_default_input = None
        self.io_default_output = None
        self.package_table = None
        self.on_load_error = None
        self.security_flags = {}
        self._addr_seed = 0x7f0000000000

    # thread/stack
    def register_thread(self, lua_thread):
        with self._thread_lock:
            self.thread_map[threading.get_ident()] = lua_thread
    def current_thread(self):
        t = self.thread_map.get(threading.get_ident())
        if t is None:
            # assume main (worker) thread
            self.thread_map[threading.get_ident()] = self.main_thread
            return self.main_thread
        return t
    def stack(self, thr=None):
        if thr is None:
            thr = self.current_thread()
        return thr.stack
    def current_frame(self, thr=None):
        s = self.stack(thr)
        return s[-1] if s else None
    def innermost_lua_frame(self, thr=None):
        s = self.stack(thr)
        for fr in reversed(s):
            if fr.is_lua:
                return fr
        return None

    def fake_addr(self, obj=None, suffix=None):
        if obj is not None:
            return id(obj)
        self._addr_seed += 0x10
        return self._addr_seed

    # errors
    def make_error(self, value):
        e = LuaError(value)
        return e
    def raise_error(self, value):
        raise LuaError(value)
    def error_with_loc(self, msg, line=None, frame=None):
        # msg bytes
        if frame is None:
            frame = self.innermost_lua_frame()
        if frame is not None:
            ln = line if line is not None else frame.line
            full = frame.chunk_display + b":" + str(ln).encode() + b": " + msg
            raise LuaError(full)
        else:
            raise LuaError(msg)
    def runtime_error(self, msg, line=None):
        self.error_with_loc(msg, line=line)
    def arg_error(self, narg, msg, fname=None, level=1):
        # Determine function name from current builtin frame if not given
        stack = self.stack()
        cur = stack[-1] if stack else None
        name = fname
        if name is None:
            if cur is not None and cur.name:
                name = cur.name
            elif cur is not None and isinstance(cur.func, BuiltinFunction) and not cur.called_from_c:
                # If called from Lua but via anonymous expression, Lua uses? test later; fallback builtin name
                name = cur.func.name
            else:
                name = b"?"
        if isinstance(name, str): name=name.encode()
        body = b"bad argument #" + str(narg).encode() + b" to '" + name + b"' (" + msg + b")"
        # location: caller frame of builtin (level?). Original adds location of caller if caller is Lua.
        # Stack indices: cur is builtin; caller is stack[-2]
        if level == 0:
            raise LuaError(body)
        caller = None
        # level 1 = immediate caller of the function that calls arg_error (which is builtin's caller)
        # In Python commons helpers like check_string called by builtin, caller still stack[-2]
        if len(stack) >= 2:
            caller = stack[-2]
        if caller is not None and caller.is_lua:
            full = caller.chunk_display + b":" + str(caller.line).encode() + b": " + body
            raise LuaError(full)
        else:
            raise LuaError(body)
    def type_error_arg(self, narg, expected, got_value, fname=None, is_no_value=False):
        if is_no_value:
            gotb = b"no value"
        else:
            gotb = lua_type(got_value)
        self.arg_error(narg, expected + b" expected, got " + gotb, fname=fname)

    # snapshot capturing done in raise wrappers in call paths
    def capture_snapshot(self, exc, thr=None):
        if exc.snapshot is None:
            stack = self.stack(thr)
            snap=[]
            for fr in stack:
                snap.append({
                    'func': fr.func, 'name': fr.name, 'namewhat': fr.namewhat, 'line': fr.line,
                    'is_lua': fr.is_lua, 'proto': fr.proto, 'chunk_display': fr.chunk_display,
                    'what': (b"main" if fr.is_main_chunk else (b"Lua" if fr.is_lua else b"C")),
                    'tail_calls': fr.tail_calls, 'called_from_c': fr.called_from_c,
                })
            exc.snapshot = snap
            exc.snapshot_thread = thr or self.current_thread()

    # metatables
    def get_metatable_obj(self, v):
        if isinstance(v, LuaTable):
            return v.metatable
        if isinstance(v, UserData):
            return v.metatable
        if isinstance(v, CData):
            # ffi may set handler to fetch
            if self.cdata_index_handler is not None:
                mt = self.cdata_index_handler('__metatable__', v)
                if mt is not None:
                    return mt
            return v.metatable_extra
        # primitives
        t = lua_type(v)
        return self.type_metatables.get(t)
    def get_metafield(self, v, name):
        mt = self.get_metatable_obj(v)
        if mt is None:
            return None
        if isinstance(mt, LuaTable):
            return mt.rawget(name)
        return None

    # conversion used throughout stdlib
    def lua_tostring(self, v, for_print=False):
        """tostring() semantics as in Lua VM __tostring etc. returns bytes or raises LuaError"""
        # if __tostring metamethod call
        # But for CData custom
        if isinstance(v, CData):
            if self.cdata_tostring_handler:
                try:
                    r = self.cdata_tostring_handler(v)
                    if r is not None:
                        return r
                except LuaError:
                    raise
                except Exception:
                    pass
            # fallthrough generic cdata repr handled later if no ffi handler
        mm = self.get_metafield(v, b"__tostring")
        if mm is not None:
            res = self.call_value(mm, [v], name=b"__tostring", namewhat=b"metamethod")
            if not res:
                # returned nothing: Lua (?) tostring returns ??? In Lua 5.1 __tostring must return string; if returns nil? tostring returns ??? probe. Approx return default? Actually lua_tostring would return nil? For builtin tostring() it checks? We'll make it raise? std tostring will handle.
                return None
            r = res[0]
            if type(r) is bytes:
                return r
            if type(r) is float:
                return fmt_num(r)
            # if __tostring returns non-string, lua (?) converts? print will error "'tostring' must return a string"
            # Our caller for print will check
            return r
        return self.default_tostring(v)

    def default_tostring(self, v):
        if v is None:
            return b"nil"
        t = type(v)
        if t is bool:
            return b"true" if v else b"false"
        if t is float or t is int:
            return fmt_num(v)
        if t is bytes:
            return v
        if isinstance(v, LuaTable):
            return b"table: 0x" + format(id(v), "x").encode()
        if isinstance(v, LuaFunction):
            return b"function: 0x" + format(id(v), "x").encode()
        if isinstance(v, BuiltinFunction):
            if v.builtin_no is not None:
                return b"function: builtin#" + str(v.builtin_no).encode()
            return b"function: 0x" + format(id(v), "x").encode()
        if isinstance(v, LuaThread):
            return b"thread: 0x" + format(id(v), "x").encode()
        if isinstance(v, CData):
            # basic for int64 literals before ffi
            ct = v.ctype
            ctn = ct if isinstance(ct, (bytes,str)) else getattr(ct,'name',None)
            if isinstance(ctn,str): ctn=ctn.encode()
            if ctn == b"int64_t":
                return str(v.value).encode() + b"LL"
            if ctn == b"uint64_t":
                return str(v.value).encode() + b"ULL"
            if ctn == b"complex":
                cv=v.value
                if isinstance(cv,complex):
                    # format like 0+10i or 1+2i ; numbers use fmt_num
                    real=fmt_num(cv.real); imag=cv.imag
                    if imag>=0 or (imag==0 and math.copysign(1,imag)>=0):
                        return real+b"+"+fmt_num(imag)+b"i"
                    else:
                        return real+b"-"+fmt_num(-imag)+b"i"
            return b"cdata<%s>: 0x%s" % ((ctn or b"?"), format(id(v),"x").encode()) if False else (b"cdata<" + (ctn or b"?") + b">: 0x" + format(id(v),"x").encode())
        if isinstance(v, UserData):
            # file handles have __tostring so not here unless cleared
            return b"userdata: 0x" + format(id(v), "x").encode()
        return b"userdata: 0x" + format(id(v), "x").encode()

    def to_string_coerce(self, v):
        # luaL_tostring-ish for concat/format %s etc (?) returns bytes or None if not string/number and no __tostring?
        # For metamethod-aware tostring API, lua_tostring returns ...
        r = self.lua_tostring(v)
        return r

    # loading
    def load_chunk(self, source_bytes, chunkname, mode=b"bt", env_table=None):
        """
        Return (LuaFunction or None, error_msg_bytes or None)
        chunkname bytes or None
        """
        # Bytecode detection
        from bcode import is_bytecode, load_bytecode, is_foreign_bytecode
        if is_bytecode(source_bytes):
            if mode and b"b" not in mode:
                # attempting load bytecode with mode text: lua error?
                return None, (make_chunk_display(chunkname or source_bytes, source_bytes) + b": attempt to load a binary chunk (mode is '" + mode + b"')")  # probe later
            try:
                fn = load_bytecode(self, source_bytes, chunkname, env_table)
                return fn, None
            except LuaError as e:
                val=e.value if type(e.value) is bytes else b"cannot load incompatible bytecode"
                return None, val
            except Exception as e:
                return None, b"cannot load incompatible bytecode"
        if is_foreign_bytecode(source_bytes):
            display = make_chunk_display(chunkname or source_bytes, source_bytes)
            return None, display + b": cannot load incompatible bytecode"
        if mode and b"t" not in mode:
            # text chunk but mode only bytecode
            display = make_chunk_display(chunkname or source_bytes, source_bytes)
            return None, display + b": attempt to load a text chunk (mode is '" + mode + b"')"  # probe later
        display = make_chunk_display(chunkname, source_bytes) if chunkname is not None else make_chunk_display(source_bytes, source_bytes)
        chunk_info = ChunkInfo(display, raw=chunkname, source_bytes=source_bytes)
        try:
            parser = Parser(source_bytes, display, chunk_info)
            proto = parser.parse_chunk()
        except ParseError as e:
            return None, e.full(display)
        # main closure
        env = env_table if env_table is not None else self.globals
        fn = LuaFunction(proto, None, env, state=self)
        fn.proto.source = source_bytes
        return fn, None

    def load_file(self, filename_bytes, mode=b"bt", env_table=None):
        # Return (fn, err) err bytes like "cannot open ..." preserving strerror
        import os
        fname_str = filename_bytes.decode('utf-8','surrogateescape')
        try:
            with open(fname_str, 'rb') as f:
                data = f.read()
        except OSError as e:
            # Lua luaL_loadfile returns error "cannot open <file>: <strerror>" ? basic loadfile returns nil + "..." probe vs CLI policy.
            err_str = e.strerror or str(e)
            return None, b"cannot open " + filename_bytes + b": " + err_str.encode()
        chunkname = b"@" + filename_bytes
        fn, err = self.load_chunk(data, chunkname, mode=mode, env_table=env_table)
        if err and err.endswith(b"cannot load incompatible bytecode"):
            # load_chunk err has display prefix already for foreign; for our format?
            pass
        return fn, err

    # ---------- Operations ----------
    def desc_for_error(self, desc, v):
        if desc:
            typ = lua_type(v)
            # Lua artefact: for cdata may be... keep
            return desc + b" (a " + typ + b" value)"
        else:
            typ = lua_type(v)
            # article a / ?
            return b"a " + typ + b" value"

    def gettable(self, obj, key, obj_desc=None, line=None):
        # loop for __index chain
        cur = obj
        for _ in range(100):
            if isinstance(cur, LuaTable):
                v = cur.rawget(key)
                if v is not None:
                    return v
                mm = self.get_metafield(cur, b"__index")
                if mm is None:
                    return None
                if isinstance(mm, (LuaFunction, BuiltinFunction)) or self._is_callable(mm):
                    res = self.call_value(mm, [cur, key], name=b"__index", namewhat=b"metamethod", line=line)
                    return res[0] if res else None
                cur = mm
                continue
            elif isinstance(cur, CData):
                if self.cdata_index_handler:
                    return self.cdata_index_handler('index', cur, key)
                # generic fallback via metatable
                mm = self.get_metafield(cur, b"__index")
                if mm is None:
                    self.error_with_loc(b"attempt to index " + self.desc_for_error(obj_desc, obj), line=line)
                if self._is_callable(mm):
                    res=self.call_value(mm,[cur,key],name=b"__index",namewhat=b"metamethod",line=line)
                    return res[0] if res else None
                cur=mm; continue
            elif isinstance(cur, UserData):
                mm = self.get_metafield(cur, b"__index")
                if mm is None:
                    self.error_with_loc(b"attempt to index " + self.desc_for_error(obj_desc, obj), line=line)
                if self._is_callable(mm):
                    res=self.call_value(mm,[cur,key],name=b"__index",namewhat=b"metamethod",line=line)
                    return res[0] if res else None
                cur=mm; continue
            else:
                # primitive with metatable
                mm = self.get_metafield(cur, b"__index")
                if mm is None:
                    self.error_with_loc(b"attempt to index " + self.desc_for_error(obj_desc, obj), line=line)
                if self._is_callable(mm):
                    res=self.call_value(mm,[cur,key],name=b"__index",namewhat=b"metamethod",line=line)
                    return res[0] if res else None
                cur=mm; continue
        self.error_with_loc(b"'__index' chain too long; possible loop", line=line)

    def settable(self, obj, key, value, obj_desc=None, line=None):
        cur = obj
        for _ in range(100):
            if isinstance(cur, LuaTable):
                existing = cur.rawget(key)
                if existing is not None:
                    cur.rawset(key, value)
                    return
                mm = self.get_metafield(cur, b"__newindex")
                if mm is None:
                    try:
                        cur.rawset(key, value)
                    except LuaError as e:
                        # add location: rawset raises "table index is nil" without loc; lua prefixes
                        if type(e.value) is bytes and b":" not in e.value[:len(cur.d)]: # crude
                            self.error_with_loc(e.value, line=line)
                        raise
                    return
                if self._is_callable(mm):
                    self.call_value(mm, [cur, key, value], name=b"__newindex", namewhat=b"metamethod", line=line)
                    return
                cur = mm; continue
            elif isinstance(cur, CData):
                if self.cdata_newindex_handler:
                    self.cdata_newindex_handler(cur, key, value)
                    return
                mm=self.get_metafield(cur,b"__newindex")
                if mm is None:
                    self.error_with_loc(b"attempt to index " + self.desc_for_error(obj_desc, obj), line=line)
                if self._is_callable(mm):
                    self.call_value(mm,[cur,key,value],name=b"__newindex",namewhat=b"metamethod",line=line); return
                cur=mm; continue
            elif isinstance(cur, UserData):
                mm=self.get_metafield(cur,b"__newindex")
                if mm is None:
                    self.error_with_loc(b"attempt to index " + self.desc_for_error(obj_desc, obj), line=line)
                if self._is_callable(mm):
                    self.call_value(mm,[cur,key,value],name=b"__newindex",namewhat=b"metamethod",line=line); return
                cur=mm; continue
            else:
                mm=self.get_metafield(cur,b"__newindex")
                if mm is None:
                    self.error_with_loc(b"attempt to index " + self.desc_for_error(obj_desc, obj), line=line)
                if self._is_callable(mm):
                    self.call_value(mm,[cur,key,value],name=b"__newindex",namewhat=b"metamethod",line=line); return
                cur=mm; continue
        self.error_with_loc(b"'__newindex' chain too long; possible loop", line=line)

    def raw_gettable(self, obj, key):
        if isinstance(obj, LuaTable):
            return obj.rawget(key)
        # used for globals
        return self.gettable(obj, key)

    def get_global(self, name_bytes, frame=None, line=None):
        if frame is None:
            frame = self.innermost_lua_frame()
        envtab = frame.fenv if frame and frame.fenv is not None else self.globals
        # getfenv could be userdata/? env must be table (checked setfenv)
        if isinstance(envtab, LuaTable):
            # globals indexing respects metatable __index of env table
            return self.gettable(envtab, name_bytes, line=line)
        return self.gettable(envtab, name_bytes, line=line)

    def set_global(self, name_bytes, value, frame=None, line=None):
        if frame is None:
            frame = self.innermost_lua_frame()
        envtab = frame.fenv if frame and frame.fenv is not None else self.globals
        self.settable(envtab, name_bytes, value, line=line)

    def _is_callable(self, v):
        if isinstance(v, (LuaFunction, BuiltinFunction)):
            return True
        # has __call metamethod
        if self.get_metafield(v, b"__call") is not None:
            return True
        if isinstance(v, CData) and self.cdata_call_handler:
            return self.cdata_call_handler('iscallable', v)
        return False

    def call_value(self, f, args, name=None, namewhat=b"", line=None, desc=None, called_from_c=False):
        # returns list
        # __call chain
        orig_f = f
        for _ in range(100):
            if isinstance(f, LuaFunction):
                return self._call_lua(f, args, name, namewhat, line, called_from_c)
            if isinstance(f, BuiltinFunction):
                return self._call_builtin(f, args, name, namewhat, line, called_from_c)
            if isinstance(f, CData) and self.cdata_call_handler:
                r = self.cdata_call_handler('call', f, args, name, line)
                if r is not None:
                    return r
            mm = self.get_metafield(f, b"__call")
            if mm is not None:
                args = [f] + list(args)
                f = mm
                # namewhat metamethod for the call metamethod? Keep original call name for traceback of metamethod function? In traceback metamethod frame namewhat=metamethod name=__call
                name = b"__call"; namewhat = b"metamethod"
                continue
            # error attempt to call
            msg = b"attempt to call " + self.desc_for_error(desc, orig_f)
            self.error_with_loc(msg, line=line)
        self.error_with_loc(b"'__call' chain too long; possible loop", line=line)

    def _call_builtin(self, f, args, name, namewhat, line, called_from_c=False):
        thr = self.current_thread()
        stack = thr.stack
        if len(stack) > MAX_CALL_DEPTH:
            # stack overflow with loc of lua caller
            self.error_with_loc(b"stack overflow", line=line)
        fr = CallInfo(f, name=name if name is not None else None, namewhat=namewhat, line=line or 0, is_lua=False, proto=None)
        fr.args = list(args)
        fr.called_from_c = called_from_c or (not stack or not stack[-1].is_lua)
        # if called from Lua via call_value from eval_call, called_from_c False; if called from builtin code (Python) via self.call_value inside another builtin, top frame is builtin (C) so mark True
        # fenv for builtin defaults globals unless set via setfenv (stored on function)
        fr.fenv = f.fenv if f.fenv is not None else self.globals
        stack.append(fr)
        try:
            # hook call
            self._call_hook(fr, b"call")
            res = f.func(self, list(args), fr)
            self._call_hook(fr, b"return")
            if res is None:
                res=[]
            elif not isinstance(res, list):
                # convenience: single value wrapped? our libs will return list; but support
                res=[res]
            return res
        except LuaError as e:
            self.capture_snapshot(e, thr)
            raise
        finally:
            # pop only if still
            if stack and stack[-1] is fr:
                stack.pop()
            elif fr in stack:
                stack.remove(fr)

    def _call_lua(self, func, args, name, namewhat, line, called_from_c=False):
        thr = self.current_thread()
        # tail call iteration loop
        cur_func = func
        cur_args = list(args)
        cur_name = name
        cur_namewhat = namewhat
        cur_line = line
        tail_calls_count = 0
        while True:
            stack = thr.stack
            if len(stack) > MAX_CALL_DEPTH:
                self.error_with_loc(b"stack overflow", line=cur_line)
            proto = cur_func.proto
            fr = CallInfo(cur_func, name=cur_name, namewhat=cur_namewhat, line=proto.line, is_lua=True, proto=proto)
            # main chunk detection: proto params vararg and linedefined 0
            fr.is_main_chunk = (proto.line == 0)
            fr.tail_calls = tail_calls_count
            fr.fenv = cur_func.fenv if cur_func.fenv is not None else self.globals
            fr.called_from_c = called_from_c
            # create function root env
            root_env = Env(parent=cur_func.captured_env, func_frame=fr)
            fr.env = root_env
            fr.args = list(cur_args)
            # params
            params = proto.params
            varargs=[]
            for i,pname in enumerate(params):
                val = cur_args[i] if i < len(cur_args) else None
                cell = root_env.define(pname, val)
                fr.active_locals.append((pname, cell))
            if proto.is_vararg:
                if len(cur_args) > len(params):
                    varargs = list(cur_args[len(params):])
                else:
                    varargs=[]
            else:
                varargs=[]
            fr.varargs = varargs
            stack.append(fr)
            try:
                self._call_hook(fr, b"call")
                # execute body block; body block itself creates child env from root_env
                self.exec_block(proto.body, root_env, fr)
                self._call_hook(fr, b"return")
                return []
            except ReturnSignal as r:
                if not r.is_tail:
                    self._call_hook(fr, b"return")
                    return r.values if r.values is not None else []
                else:
                    # tail call
                    next_func = r.tail_func
                    next_args = r.tail_args
                    next_name = r.tail_name
                    # pop frame before handling (finally will pop also; we need to exit try and continue loop)
                    # set variables and fallthrough to finally pop, then continue outer while via flag
                    tail_calls_count += 1
                    # Effectively need to break out of try and loop; we can capture and handle after finally
                    # Python finally will pop; we use a trick: store pending tail and raise internal sentinel? Instead handle here: pop ourselves; finally will check existence.
                    # pop frame:
                    if stack and stack[-1] is fr:
                        stack.pop()
                    # Now decide next
                    if isinstance(next_func, LuaFunction):
                        cur_func = next_func; cur_args = next_args; cur_name = next_name; cur_line = r.tail_line
                        # continue while loop; need to bypass finally duplicate pop logic it's safe.
                        # Use for-break via goto style: set a flag variable and return from except to bottom of loop iteration.
                        # Python 'continue' inside except inside while with finally attached to try... The try is inside while True: continue will trigger finally.
                        continue
                    else:
                        # call other callable and return its results (stack popped)
                        return self.call_value(next_func, next_args, name=next_name, namewhat=r.__dict__.get('tail_namewhat', b"") if hasattr(r,'__dict__') else b"", line=r.tail_line, called_from_c=False)
            except LuaError as e:
                self.capture_snapshot(e, thr)
                raise
            finally:
                if stack and stack[-1] is fr:
                    stack.pop()
                elif fr in stack:
                    try: stack.remove(fr)
                    except: pass
            # If we reached here due to ReturnSignal non-tail handled? returns above. loop shouldn't continue
            # But continue from tail Lua case already continues loop.
            # Prevent infinite
            break

    def _call_hook(self, fr, event):
        # Minimal hook support: stored in self.hooks
        try:
            thr=self.current_thread()
            h=self.hooks.get(thr)
            if not h:
                return
            func, mask, count = h[0], h[1], h[2]
            # mask bytes contain c/r/l
            emit=False
            if event==b"call" and b"c" in mask:
                emit=True
            elif event==b"return" and b"r" in mask:
                emit=True
            elif event==b"line" and b"l" in mask:
                emit=True
            elif event==b"count" and count>0:
                emit=True
            elif event==b"tail call" and b"c" in mask:
                emit=True
            if not emit:
                return
            # Avoid reentrancy: temporarily disable hook while calling hook function
            saved=self.hooks.pop(thr,None)
            try:
                args=[event]
                if event==b"line":
                    args.append(float(fr.line))
                self.call_value(func, args, name=b"hook", called_from_c=True)
            finally:
                self.hooks[thr]=saved
        except LuaError:
            raise
        except Exception:
            pass

    # ------------ Execution ---------------
    def exec_block(self, block, env, frame, repeat_cond=None):
        # block tuple ('block', line, stmts, labels)
        # if repeat_cond is not None, execute as repeat loop: after block execution, evaluate cond in block env; if false loop.
        kind, bline, stmts, labels = block
        # For regular block, execute once
        while True:
            block_env = Env(parent=env, func_frame=frame)
            base_locals_count = len(frame.active_locals)
            pc = 0
            label_snapshots = {}  # name -> (vars copy, locals_count)
            try:
                while pc < len(stmts):
                    stmt = stmts[pc]
                    pc += 1
                    try:
                        self.exec_stmt(stmt, block_env, frame)
                        if stmt[0]=='label':
                            nm=stmt[2]
                            label_snapshots[nm]=(dict(block_env.vars), len(frame.active_locals))
                    except GotoSignal as gs:
                        if gs.label in labels:
                            target_pc = labels[gs.label]
                            # restore env snapshot if known
                            if gs.label in label_snapshots:
                                vars_copy, loc_count = label_snapshots[gs.label]
                                block_env.vars = dict(vars_copy)
                                # truncate active locals to snapshot
                                del frame.active_locals[loc_count:]
                            else:
                                # forward jump: locals that will be declared are not yet; truncate to base+? keep current if label is at end (?) If label at end statement position maybe locals should expire if it's last statement
                                if target_pc >= len(stmts)-1:
                                    # last label: expire this block's locals
                                    block_env.vars = {}
                                    del frame.active_locals[base_locals_count:]
                                # else keep vars as they are (could include locals declared before label if jumped from nested block after they have been declared; if jumped before declared, they aren't in vars)
                            pc = target_pc
                            continue
                        raise
                # finished stmts
                if repeat_cond is None:
                    return
                # repeat loop: evaluate cond in block_env
                frame.line = repeat_cond[1]
                cond_val = self.eval_expr(repeat_cond, block_env, frame)
                # truncate locals before next iter or exit
                del frame.active_locals[base_locals_count:]
                if lua_truthy(cond_val):
                    return
                # loop again with fresh block_env (outer while)
                continue
            finally:
                # truncate locals of this block if exiting normally or via exceptions (repeat already truncated on cond path but it's okay)
                if len(frame.active_locals) > base_locals_count:
                    # But if repeat_cond loop continues, finally of this iteration? Note: finally executes on return/continue of outer while? In Python, continuing outer while from inside try triggers finally, which truncates (desired). On normal non-repeat return triggers.
                    del frame.active_locals[base_locals_count:]
            # if repeat_cond and not truthy we already used continue which goes to next while (finally ran). Unreachable
            # To prevent infinite in non-repeat, break
            break

    def exec_stmt(self, stmt, env, frame):
        kind = stmt[0]; line=stmt[1]
        frame.line = line
        # line hook
        if self.hooks.get(self.current_thread()):
            self._call_hook(frame, b"line")
        if kind=='do':
            self.exec_block(stmt[2], env, frame)
        elif kind=='while':
            cond=stmt[2]; blk=stmt[3]
            while True:
                frame.line = line
                c=self.eval_expr(cond, env, frame)
                if not lua_truthy(c):
                    break
                try:
                    self.exec_block(blk, env, frame)
                except BreakSignal:
                    break
        elif kind=='repeat':
            blk=stmt[2]; cond=stmt[3]
            try:
                self.exec_block(blk, env, frame, repeat_cond=cond)
            except BreakSignal:
                pass
        elif kind=='if':
            clauses=stmt[2]; else_blk=stmt[3]
            done=False
            for cond, blk, cline in clauses:
                frame.line = cline
                if lua_truthy(self.eval_expr(cond, env, frame)):
                    self.exec_block(blk, env, frame)
                    done=True
                    break
            if not done and else_blk is not None:
                self.exec_block(else_blk, env, frame)
        elif kind=='fornum':
            _,_, varname, start_expr, limit_expr, step_expr, blk = stmt
            frame.line=line
            start_v=self.eval_expr(start_expr, env, frame)
            limit_v=self.eval_expr(limit_expr, env, frame)
            step_v=self.eval_expr(step_expr, env, frame) if step_expr is not None else 1.0
            start_n=to_number(start_v)
            if start_n is None:
                self.error_with_loc(b"'for' initial value must be a number", line=line)
            limit_n=to_number(limit_v)
            if limit_n is None:
                self.error_with_loc(b"'for' limit must be a number", line=line)
            step_n=to_number(step_v)
            if step_n is None:
                self.error_with_loc(b"'for' step must be a number", line=line)
            idx=start_n
            # numeric for condition
            try:
                while (step_n>0 and idx<=limit_n) or (step_n<0 and idx>=limit_n) or (step_n==0 and idx==idx): # step 0: Lua? 5.1 loop executes while ?? see. We'll treat as infinite unless break (like Lua while condition step>0? lua 5.1 code: if step>0 cond idx<=limit else idx>=limit; step0 goes else: would loop if idx>=limit. ok handle below remap)
                    # correct step0 semantics re-evaluate: If step==0 earlier loop condition above uses third clause always true, may loop infinite even if start > limit. Let's implement explicitly:
                    # Actually break control: to avoid breaking step0 logic, the while condition entered; fine.
                    iter_env=Env(parent=env, func_frame=frame)
                    cell=iter_env.define(varname, float(idx))
                    frame.active_locals.append((varname, cell))
                    # also add hidden for debugging? "(for index)" etc names would be before? Lua locals order: (for index),(for limit),(for step), varname. debug.getlocal may see hidden. Add hidden cells before body each iter? But our visible loop var should be index 4? Real Lua/debug stacks show vars at block start maybe. Keep only var for now; debug tests on for loops could see diff.
                    try:
                        self.exec_block(blk, iter_env, frame)
                    except BreakSignal:
                        # pop var local
                        if frame.active_locals and frame.active_locals[-1][1] is cell:
                            frame.active_locals.pop()
                        else:
                            # truncate search
                            for i in range(len(frame.active_locals)-1,-1,-1):
                                if frame.active_locals[i][1] is cell:
                                    del frame.active_locals[i:]; break
                        raise # will be caught below
                    # remove var local tracking
                    # It may have been truncated by exec_block of blk? exec_block truncates to count at its entry which includes cell, so after body cell still at tail.
                    if frame.active_locals and frame.active_locals[-1][1] is cell:
                        frame.active_locals.pop()
                    idx += step_n
                    # prevent infinite when step==0? Lua would loop; keep like original (scripts shouldn't)
                    # Re-evaluate loop condition at top while; but if step==0 and start>limit originally this branch could be erroneous. Adjust: break out if step==0??? Not now.
            except BreakSignal:
                pass
        elif kind=='forgen':
            _,_, names, exprs, blk = stmt
            frame.line=line
            vals=self.eval_exprlist_adjust(exprs, env, frame, 3)
            iter_func, state_val, control = vals[0], vals[1], vals[2]
            try:
                while True:
                    frame.line=line
                    res=self.call_value(iter_func, [state_val, control], line=line)
                    if not res or res[0] is None:
                        break
                    control=res[0]
                    iter_env=Env(parent=env, func_frame=frame)
                    cells=[]
                    for i,nm in enumerate(names):
                        v=res[i] if i < len(res) else None
                        cell=iter_env.define(nm, v)
                        cells.append(cell)
                        frame.active_locals.append((nm, cell))
                    try:
                        self.exec_block(blk, iter_env, frame)
                    except BreakSignal:
                        # pop cells
                        # truncate from first cell pos
                        # find
                        for i in range(len(frame.active_locals)):
                            if frame.active_locals[i][1] is cells[0]:
                                del frame.active_locals[i:]; break
                        raise
                    # pop cells track
                    for i in range(len(frame.active_locals)):
                        if frame.active_locals[i][1] is cells[0]:
                            del frame.active_locals[i:]; break
            except BreakSignal:
                pass
        elif kind=='local':
            names=stmt[2]; exprs=stmt[3]
            if exprs:
                vals=self.eval_exprlist_adjust(exprs, env, frame, len(names))
            else:
                vals=[None]*len(names)
            for nm, v in zip(names, vals):
                cell=env.define(nm, v)
                frame.active_locals.append((nm, cell))
        elif kind=='localfunc':
            nm=stmt[2]; func_expr=stmt[3]
            cell=env.define(nm, None)
            frame.active_locals.append((nm, cell))
            fn=self.eval_expr(func_expr, env, frame)
            cell.v=fn
        elif kind=='assign':
            targets=stmt[2]; exprs=stmt[3]
            self.exec_assign(targets, exprs, env, frame, line)
        elif kind=='callstmt':
            frame.line=line
            self.eval_expr(stmt[2], env, frame)  # discard
        elif kind=='return':
            exprs=stmt[2]
            frame.line=line
            if len(exprs)==1 and exprs[0][0] in ('call','methodcall'):
                # tail call
                tail_func, tail_args, tail_name, tail_nw = self.prepare_call(exprs[0], env, frame)
                r=ReturnSignal(None)
                r.is_tail=True; r.tail_func=tail_func; r.tail_args=tail_args; r.tail_name=tail_name; r.tail_line=line
                # store namewhat hack on object attribute via __dict__? ReturnSignal has no slots, can assign
                r.tail_namewhat=tail_nw
                raise r
            vals=[]
            if exprs:
                vals=self.eval_exprlist_multi(exprs, env, frame)
            raise ReturnSignal(vals)
        elif kind=='break':
            raise BreakSignal()
        elif kind=='goto':
            raise GotoSignal(stmt[2])
        elif kind=='label':
            pass
        else:
            raise Exception(f"unknown stmt {kind}")

    def exec_assign(self, targets, exprs, env, frame, line):
        # Prepare refs
        refs=[]
        for tgt in targets:
            if tgt[0]=='var':
                nm=tgt[2]
                cell, kind = env.lookup(nm, frame)
                if cell is not None:
                    refs.append(('cell', cell))
                else:
                    refs.append(('global', nm))
            elif tgt[0]=='index':
                # evaluate obj and key
                obj_expr=tgt[2]; key_expr=tgt[3]
                obj, obj_desc=self.eval_with_desc(obj_expr, env, frame)
                key=self.eval_expr(key_expr, env, frame)
                refs.append(('index', obj, key, obj_desc, tgt[1]))
            else:
                # parser shouldn't produce others; if paren var is syntax error in lua; we treat as error later
                # Evaluate and error "syntax error?" etc parser should check; treat generic
                self.error_with_loc(b"syntax error near '='", line=line)  # placeholder
        vals=self.eval_exprlist_adjust(exprs, env, frame, len(targets))
        for ref, v in zip(refs, vals):
            if ref[0]=='cell':
                ref[1].v=v
            elif ref[0]=='global':
                frame.line=line
                self.set_global(ref[1], v, frame=frame, line=line)
            elif ref[0]=='index':
                frame.line=ref[4]
                self.settable(ref[1], ref[2], v, obj_desc=ref[3], line=ref[4])

    # Reference preparation for call exprs, returns func,args,name,namewhat
    def prepare_call(self, node, env, frame):
        if node[0]=='call':
            _, cline, fexpr, arg_exprs = node
            fval, descname, name, namewhat = self.eval_func_target(fexpr, env, frame)
            frame.line=cline
            args=self.eval_exprlist_multi(arg_exprs, env, frame) if arg_exprs else []
            return fval, args, name, namewhat
        elif node[0]=='methodcall':
            _, cline, obj_expr, mname, arg_exprs = node
            obj, obj_desc=self.eval_with_desc(obj_expr, env, frame)
            frame.line=cline
            fval=self.gettable(obj, mname, obj_desc=obj_desc, line=cline)
            args=self.eval_exprlist_multi(arg_exprs, env, frame) if arg_exprs else []
            return fval, [obj]+args, mname, b"method"
        else:
            raise Exception("prepare_call non-call")

    def eval_func_target(self, fexpr, env, frame):
        # returns (value, desc, name, namewhat)
        if fexpr[0]=='var':
            nm=fexpr[2]
            cell, kind=env.lookup(nm, frame)
            if cell is not None:
                desc= kind + b" '" + nm + b"'"  # kind is local/upvalue
                return cell.v, desc, nm, kind
            else:
                frame.line=fexpr[1]
                val=self.get_global(nm, frame=frame, line=fexpr[1])
                return val, b"global '" + nm + b"'", nm, b"global"
        elif fexpr[0]=='index':
            obj_expr=fexpr[2]; key_expr=fexpr[3]
            obj, obj_desc=self.eval_with_desc(obj_expr, env, frame)
            key=self.eval_expr(key_expr, env, frame)
            frame.line=fexpr[1]
            val=self.gettable(obj, key, obj_desc=obj_desc, line=fexpr[1])
            if key_expr[0]=='string':
                fname=key_expr[2]
                return val, b"field '" + fname + b"'", fname, b"field"
            else:
                return val, None, None, b""
        else:
            val=self.eval_expr(fexpr, env, frame)
            return val, None, None, b""

    def eval_with_desc(self, node, env, frame):
        # returns (value, desc_bytes_or_None) where desc is like b"local 'x'" / b"field 'y'" without parenthetical.
        if node[0]=='var':
            nm=node[2]
            cell, kind=env.lookup(nm, frame)
            if cell is not None:
                return cell.v, kind + b" '" + nm + b"'"
            else:
                frame.line=node[1]
                return self.get_global(nm, frame=frame, line=node[1]), b"global '" + nm + b"'"
        elif node[0]=='index':
            val=self.eval_expr(node, env, frame)
            key_expr=node[3]
            if key_expr[0]=='string':
                return val, b"field '" + key_expr[2] + b"'"
            return val, None
        elif node[0]=='paren':
            return self.eval_expr(node, env, frame), None
        else:
            return self.eval_expr(node, env, frame), None

    def eval_exprlist_adjust(self, exprs, env, frame, n):
        vals=self.eval_exprlist_multi(exprs, env, frame)
        if len(vals) < n:
            vals += [None]*(n-len(vals))
        elif len(vals) > n:
            vals = vals[:n]
        return vals

    def eval_exprlist_multi(self, exprs, env, frame):
        if not exprs:
            return []
        vals=[]
        for e in exprs[:-1]:
            vals.append(self.eval_expr(e, env, frame))
        last=exprs[-1]
        if last[0] in ('call','methodcall','vararg'):
            vals.extend(self.eval_expr_multi(last, env, frame))
        else:
            vals.append(self.eval_expr(last, env, frame))
        return vals

    def eval_expr_multi(self, node, env, frame):
        # returns list for multi-valued exprs
        if node[0]=='call' or node[0]=='methodcall':
            fval, args, name, namewhat=self.prepare_call(node, env, frame)
            frame.line=node[1]
            # Build desc for call errors from name/namewhat? call_value desc uses name detection via original target; reconstruct
            # The prepare_call lost desc; recompute desc for call node target quickly if call fails callable check. To have proper desc, we inject: if name, desc as per namewhat categories.
            desc=None
            if name is not None:
                if namewhat in (b"local", b"upvalue", b"global"):
                    desc=namewhat + b" '" + name + b"'"
                elif namewhat==b"field":
                    desc=b"field '" + name + b"'"
                elif namewhat==b"method":
                    desc=b"method '" + name + b"'"
            return self.call_value(fval, args, name=name, namewhat=namewhat, line=node[1], desc=desc)
        elif node[0]=='vararg':
            frame.line=node[1]
            # check current function is vararg? Parser would have allowed ... in non-vararg? Lua error at parse: "cannot use '...' outside a vararg function near '...'" - parser not checking yet. VM: if proto not vararg, error (parse-like). Find frame proto
            if not frame.proto.is_vararg:
                self.error_with_loc(b"cannot use '...' outside a vararg function", line=node[1]) # message differ at runtime; parse validation TODO
            return list(frame.varargs)
        else:
            return [self.eval_expr(node, env, frame)]

    def eval_expr(self, node, env, frame):
        kind=node[0]; line=node[1]
        # line tracking: only update for some nodes? Setting line for many helps error line for operators. function calls set their own.
        # We'll set at ops/call/index.
        if kind=='number':
            return float(node[2])
        elif kind=='cdata_num':
            return self._make_cdata_num(node[2])
        elif kind=='string':
            return node[2]
        elif kind=='nil':
            return None
        elif kind=='bool':
            return node[2]
        elif kind=='vararg':
            ml=self.eval_expr_multi(node, env, frame)
            return ml[0] if ml else None
        elif kind=='var':
            nm=node[2]
            cell, _kind=env.lookup(nm, frame)
            if cell is not None:
                return cell.v
            frame.line=line
            return self.get_global(nm, frame=frame, line=line)
        elif kind=='paren':
            return self.eval_expr(node[2], env, frame)
        elif kind=='function':
            proto=node[2]
            fenv = frame.fenv if frame else self.globals
            fn=LuaFunction(proto, env, fenv, state=self)
            return fn
        elif kind=='table':
            return self.eval_table(node, env, frame)
        elif kind=='index':
            obj_expr=node[2]; key_expr=node[3]
            obj, obj_desc=self.eval_with_desc(obj_expr, env, frame)
            key=self.eval_expr(key_expr, env, frame)
            frame.line=line
            return self.gettable(obj, key, obj_desc=obj_desc, line=line)
        elif kind=='call' or kind=='methodcall':
            ml=self.eval_expr_multi(node, env, frame)
            return ml[0] if ml else None
        elif kind=='unop':
            op=node[2]; operand=node[3]
            frame.line=line
            val, desc=self.eval_with_desc(operand, env, frame)
            frame.line=line
            return self.do_unop(op, val, desc, line)
        elif kind=='binop':
            op=node[2]; leftn=node[3]; rightn=node[4]
            if op==b"and":
                lv=self.eval_expr(leftn, env, frame)
                if not lua_truthy(lv):
                    frame.line=line
                    return lv
                return self.eval_expr(rightn, env, frame)
            if op==b"or":
                lv=self.eval_expr(leftn, env, frame)
                if lua_truthy(lv):
                    frame.line=line
                    return lv
                return self.eval_expr(rightn, env, frame)
            # eval left/right with descs
            lv, ldesc=self.eval_with_desc(leftn, env, frame)
            rv, rdesc=self.eval_with_desc(rightn, env, frame)
            frame.line=line
            return self.do_binop(op, lv, rv, ldesc, rdesc, line)
        else:
            raise Exception(f"unknown expr {kind}")

    def _make_cdata_num(self, valtuple):
        # valtuple = ("suffix", floatvalue, suffixbytes, corebytes)
        _, fval, suffix, core = valtuple
        suf = suffix.upper()
        if suf==b"I":
            cd=CData(b"complex", complex(0, float(fval)))
            return cd
        # int64 / uint64
        if core.lower().startswith(b"0x"):
            ival=int(core[2:],16)
        elif core.lower().startswith(b"0b"):
            ival=int(core[2:],2)
        else:
            ival=int(core,10)
        if suf in (b"ULL",b"LLU"):
            return CData(b"uint64_t", iva_wrap_u64(ival))
        else: # LL
            return CData(b"int64_t", wrap_i64(ival))

    def eval_table(self, node, env, frame):
        fields=node[2]
        tbl=LuaTable()
        list_index=1
        for idx,field in enumerate(fields):
            is_last = (idx==len(fields)-1)
            fkind=field[0]; fline=field[1]
            frame.line=fline
            if fkind=='key':
                k=self.eval_expr(field[2], env, frame)
                v=self.eval_expr(field[3], env, frame)
                if k is None:
                    # Lua table constructor with nil key: error? "table index is nil" but actually construction may skip? probe later.
                    # Using rawset raises location-less error; surround
                    try: tbl.rawset(k,v)
                    except LuaError as e: self.error_with_loc(e.value,line=fline)
                elif type(k) is float and math.isnan(k):
                    try: tbl.rawset(k,v)
                    except LuaError as e: self.error_with_loc(e.value,line=fline)
                else:
                    tbl.rawset(k,v)
            elif fkind=='namekey':
                k=field[2]
                v=self.eval_expr(field[3], env, frame)
                tbl.rawset(k,v)
            elif fkind=='list':
                expr=field[2]
                if is_last and expr[0] in ('call','methodcall','vararg'):
                    vals=self.eval_expr_multi(expr, env, frame)
                    for val in vals:
                        tbl.rawset(float(list_index), val)
                        list_index+=1
                else:
                    v=self.eval_expr(expr, env, frame)
                    tbl.rawset(float(list_index), v)
                    list_index+=1
        return tbl

    # operations
    def do_unop(self, op, val, desc, line):
        if op==b"not":
            return not lua_truthy(val)
        elif op==b"-":
            # cdata
            if isinstance(val, CData):
                r=self._cdata_arith(b"__unm", val, None, line)
                if r is not NotImplemented:
                    return r
            n=to_number(val)
            if n is not None:
                return -n
            mm=self.get_metafield(val, b"__unm")
            if mm is not None:
                res=self.call_value(mm,[val],name=b"__unm",namewhat=b"metamethod",line=line)
                return res[0] if res else None
            self.error_with_loc(b"attempt to perform arithmetic on " + self.desc_for_error(desc, val), line=line)
        elif op==b"#":
            if type(val) is bytes:
                return float(len(val))
            if isinstance(val, LuaTable):
                # __len for tables? 5.1 no, but LuaJIT maybe if 5.2 compat? Check later. Use raw length unless meta and ??? Let's raw.
                return float(val.length())
            if isinstance(val, UserData):
