# Lua pattern matching engine (byte oriented)
from core import LuaError

class PatternError(Exception):
    def __init__(self,msg):
        self.msg=msg

def is_alpha(c): return (65<=c<=90) or (97<=c<=122)
def is_digit(c): return 48<=c<=57
def is_space(c): return c in (9,10,11,12,13,32)
def is_lower(c): return 97<=c<=122
def is_upper(c): return 65<=c<=90
def is_alnum(c): return is_alpha(c) or is_digit(c)
def is_cntrl(c): return c<32 or c==127
def is_punct(c): return (33<=c<=126) and not is_alnum(c) and c!=32  # printable not alnum/space
def is_graph(c): return 33<=c<=126  # %g : printable except space
def is_hex(c): return is_digit(c) or (65<=c<=70) or (97<=c<=102)
def is_print(c): return 32<=c<=126

CLASS_FUNCS={
  ord('a'):is_alpha, ord('c'):is_cntrl, ord('d'):is_digit, ord('g'):is_graph, ord('l'):is_lower,
  ord('p'):is_punct, ord('s'):is_space, ord('u'):is_upper, ord('w'):is_alnum, ord('x'):is_hex,
}

def match_class(c, cl):
    # c byte int or None? Lua uses char; for frontier, out of range uses 0?
    if cl in CLASS_FUNCS:
        return CLASS_FUNCS[cl](c)
    if 65<=cl<=90:
        low=cl+32
        if low in CLASS_FUNCS:
            return not CLASS_FUNCS[low](c)
    return c==cl

class Matcher:
    def __init__(self, s, p):
