        self.captures=[]  # list of [start, length] length -1 unfinished, -2 position (start is pos+1 as number?) We'll store position value type distinct
        # capture entry: dict start (0-index), len (int or -1 unfinished or -2 position)
        self.level=0

    def _class_end(self, pi):
        # return index after pattern item starting at pi
        p=self.p
        if pi>=len(p):
            raise PatternError(b"malformed pattern (ends with '%')")
        c=p[pi]
        if c==ord('%'):
            if pi+1>=len(p):
                raise PatternError(b"malformed pattern (ends with '%')")
            return pi+2
        if c==ord('['):
            i=pi+1
            if i<len(p) and p[i]==ord('^'):
                i+=1
            # first loop at least one?
            first=True
            while True:
                if i>=len(p):
                    raise PatternError(b"malformed pattern (missing ']')")
                ch=p[i]; i+=1
                if ch==ord('%') and i<len(p):
                    i+=1 # skip escaped
                elif ch==ord(']') and not first:
                    return i
                first=False
        return pi+1

    def _match_bracket_class(self, c, pi, ec):
        # pi at '['; ec index of ']'? class_end returns after ']' so ec-1 is ']'
        p=self.p
        sig=True; i=pi+1
        if i<ec and p[i]==ord('^'):
            sig=False; i+=1
        while i<ec-1:
            ch=p[i]
            if ch==ord('%'):
