        c=self.s[si]; p=self.p
        pc=p[pi]
        if pc==ord('.'):
            return True
        if pc==ord('%'):
            return match_class(c,p[pi+1])
        if pc==ord('['):
            return self._match_bracket_class(c,pi,ec)
        return pc==c

    def _match_balance(self, si, pi):
        # pi at '%' and next 'b'; pi+2 = open, pi+3=close
        p=self.p
        if pi+3>=len(p):
