# Minimal bytecode handling: own deterministic text-based dump format.
# Real LuaJIT bytecode starts with ESC 'L' 'J' ; Lua 5.1 with ESC 'L' 'u' 'a'
from core import LuaError

OUR_MAGIC = b"\x1bMUSPYLJ1\n"

def is_bytecode(data):
    return data.startswith(OUR_MAGIC)
def is_foreign_bytecode(data):
    return data.startswith(b"\x1bLJ") or data.startswith(b"\x1bLua") or data.startswith(b"\x1bLJP") or data[:1]==b"\x1b"
    # Last condition too broad? Lua treats first byte ESC as bytecode marker; source text cannot start with ESC normally. Keep for \x1b cases.
def load_bytecode(state, data, chunkname, env_table=None):
    # Format: magic + source bytes of a Lua expression returning a function? Stored by string.dump implementation:
    # payload is: b"return " + function source? Or full chunk source for main chunk dump? Our string.dump only for LuaFunctions will store source chunk & function reconstruct instruction.
    # Payload format implemented in stdlib.dump: line1 type, rest ...
    from core import LuaError
    payload = data[len(OUR_MAGIC):]
    # payload is a Lua chunk source which returns a function.
    fn, err = state.load_chunk(payload, chunkname or b"=(binary chunk)", mode=b"t", env_table=env_table)
    if err:
        raise LuaError(err)
    # call chunk to obtain function
    res = state.call_value(fn, [], called_from_c=True)
    if not res:
        raise LuaError(b"cannot load incompatible bytecode")
    return res[0]
def dump_function(state, func):
    # Find function source slice if available from proto.source_slice; else reconstruct from chunk source?
    proto = func.proto
    if getattr(proto, 'source_slice', None):
        src = proto.source_slice
        payload = b"return " + src
        return OUR_MAGIC + payload
    # If main chunk, proto.source is full chunk: wrap as function() ... end is not equivalent for return values; dump main chunks rarely via string.dump(main)? load() returns main function; dumping it then loading should execute chunk. Our payload: return function(...) <source> end
    if getattr(proto, 'source', None):
        payload = b"return function(...)\n" + proto.source + b"\nend"
        return OUR_MAGIC + payload
    raise LuaError(b"unable to dump given function")
