# Lua pattern matching engine (byte oriented)
from core import LuaError

class PatternError(Exception):
    def __init__(self,msg):
        self.msg=msg

def is_alpha(c): return (65<=c<=90) or (97<=c<=122)
def is_digit(c): return 48<=c<=57
def is_space(c): return c in (9,10,11,12,13,32)
def is_lower(c): return 97<=c<=122
def is_upper(c): return 65<=c<=90
def is_alnum(c): return is_alpha(c) or is_digit(c)
def is_cntrl(c): return c<32 or c==127
def is_punct(c): return (33<=c<=126) and not is_alnum(c) and c!=32  # printable not alnum/space
def is_graph(c): return 33<=c<=126  # %g : printable except space
def is_hex(c): return is_digit(c) or (65<=c<=70) or (97<=c<=102)
def is_print(c): return 32<=c<=126

CLASS_FUNCS={
  ord('a'):is_alpha, ord('c'):is_cntrl, ord('d'):is_digit, ord('g'):is_graph, ord('l'):is_lower,
  ord('p'):is_punct, ord('s'):is_space, ord('u'):is_upper, ord('w'):is_alnum, ord('x'):is_hex,
}

def match_class(c, cl):
    # c byte int or None? Lua uses char; for frontier, out of range uses 0?
    if cl in CLASS_FUNCS:
        return CLASS_FUNCS[cl](c)
    if 65<=cl<=90:
        low=cl+32
        if low in CLASS_FUNCS:
            return not CLASS_FUNCS[low](c)
    return c==cl

class Matcher:
    def __init__(self, s, p):
        self.s=s; self.p=p; self.slen=len(s); self.plen=len(p)
        self.captures=[]  # list of [start, length] length -1 unfinished, -2 position (start is pos+1 as number?) We'll store position value type distinct
        # capture entry: dict start (0-index), len (int or -1 unfinished or -2 position)
        self.level=0

    def _class_end(self, pi):
        # return index after pattern item starting at pi
        p=self.p
        if pi>=len(p):
            raise PatternError(b"malformed pattern (ends with '%')")
        c=p[pi]
        if c==ord('%'):
            if pi+1>=len(p):
                raise PatternError(b"malformed pattern (ends with '%')")
            return pi+2
        if c==ord('['):
            i=pi+1
            if i<len(p) and p[i]==ord('^'):
                i+=1
            # first loop at least one?
            first=True
            while True:
                if i>=len(p):
                    raise PatternError(b"malformed pattern (missing ']')")
                ch=p[i]; i+=1
                if ch==ord('%') and i<len(p):
                    i+=1 # skip escaped
                elif ch==ord(']') and not first:
                    return i
                first=False
        return pi+1

    def _match_bracket_class(self, c, pi, ec):
        # pi at '['; ec index of ']'? class_end returns after ']' so ec-1 is ']'
        p=self.p
        sig=True; i=pi+1
        if i<ec and p[i]==ord('^'):
            sig=False; i+=1
        while i<ec-1:
            ch=p[i]
            if ch==ord('%'):
                i+=1
                if i>=ec:
                    break
                if match_class(c,p[i]):
                    return sig
                i+=1
            elif i+2<ec-1 and p[i+1]==ord('-'):
                # range   ; note condition based Lua: if p+2 < ec and *(p+1)=='-'
                if p[i]<=c<=p[i+2]:
                    return sig
                i+=3
            else:
                if ch==c:
                    return sig
                i+=1
        return not sig

    def _single_match(self, si, pi, ec):
        if si>=self.slen:
            return False
        c=self.s[si]; p=self.p
        pc=p[pi]
        if pc==ord('.'):
            return True
        if pc==ord('%'):
            return match_class(c,p[pi+1])
        if pc==ord('['):
            return self._match_bracket_class(c,pi,ec)
        return pc==c

    def _match_balance(self, si, pi):
        # pi at '%' and next 'b'; pi+2 = open, pi+3=close
        p=self.p
        if pi+3>=len(p):
            raise PatternError(b"missing arguments to '%b' in pattern")
        b=p[pi+2]; e=p[pi+3]
        if si>=self.slen or self.s[si]!=b:
            return None
        cont=1; i=si+1
        while i<self.slen:
            if self.s[i]==e:
                cont-=1
                if cont==0:
                    return i+1
            elif self.s[i]==b:
                cont+=1
            i+=1
        return None

    def _match_capture(self, si, idx_digit):
        # idx_digit char '1'..'9'
        n=idx_digit-49 # zero based
        if n<0 or n>=len(self.captures):
            raise PatternError(b"invalid capture index")
        cap=self.captures[n]
        if cap['len']==-1:
            raise PatternError(b"unfinished capture")
        if cap['len']==-2:
            raise PatternError(b"invalid capture index") # position cap used as ref? lua checks? check_capture allows? it errors invalid capture index for position? Actually captured position length -2, get capture returns positions; backref probably fails.
        l=cap['len']
