        # what 'full' or 'pos'
        if len(self.captures)>=32:
            raise PatternError(b"too many captures")
        self.captures.append({'start':si,'len':-2 if what=='pos' else -1})
        res=self._match(si,pi)
        if res is None:
            self.captures.pop()
        return res

    def _end_capture(self, si, pi):
        # find last unfinished
        idx=-1
        for i in range(len(self.captures)-1,-1,-1):
            if self.captures[i]['len']==-1:
                idx=i; break
        if idx==-1:
            raise PatternError(b"invalid pattern capture")
        saved=self.captures[idx]['len']
        self.captures[idx]['len']=si-self.captures[idx]['start']
        res=self._match(si,pi)
        if res is None:
            self.captures[idx]['len']=saved
        return res

