        # greedy *
        n=0
        while self._single_match(si+n, pi, ec):
            n+=1
        while n>=0:
            res=self._match(si+n, ec+1)
            if res is not None:
                return res
            n-=1
        return None
    def _min_expand(self, si, pi, ec):
        while True:
            res=self._match(si, ec+1)
            if res is not None:
                return res
            if self._single_match(si, pi, ec):
                si+=1
            else:
                return None

    def _match(self, si, pi):
        p=self.p
        while True:
            if pi>=len(p):
                return si
            c=p[pi]
            if c==ord('('):
                if pi+1<len(p) and p[pi+1]==ord(')'):
                    return self._start_capture(si, pi+2, 'pos')
                else:
                    return self._start_capture(si, pi+1, 'full')
            if c==ord(')'):
                return self._end_capture(si, pi+1)
            if c==ord('$') and pi==len(p)-1:
                return si if si==self.slen else None
            if c==ord('%'):
                nc=p[pi+1] if pi+1<len(p) else None
                if nc==ord('b'):
                    r=self._match_balance(si,pi)
                    if r is None: return None
                    si=r; pi+=4; continue
                if nc==ord('f'):
                    # frontier %f[set]
                    pi+=2
                    if pi>=len(p) or p[pi]!=ord('['):
                        raise PatternError(b"missing '[' after '%f' in pattern")
                    ec=self._class_end(pi)
                    # previous char and next char classes
                    prev = self.s[si-1] if si>0 else 0
                    nxt = self.s[si] if si<self.slen else 0
                    # Lua uses 0 as sentinel; match_bracket_class for 0 char. Our function accepts c int
                    if self._match_bracket_class(prev, pi, ec):
                        return None
                    if not self._match_bracket_class(nxt, pi, ec):
                        return None
                    pi=ec; continue
                if nc is not None and 49<=nc<=57:
                    r=self._match_capture(si,nc)
                    if r is None: return None
                    si=r; pi+=2; continue
                # else fallthrough to class item
            # pattern item plus suffix
            ec=self._class_end(pi)
            suffix=p[ec] if ec<len(p) else None
            single=self._single_match(si, pi, ec)
            if not single:
                if suffix in (ord('*'),ord('?'),ord('-')):
                    pi=ec+1; continue
                else:
                    return None
            # single matches
            if suffix==ord('?'):
                res=self._match(si+1, ec+1)
                if res is not None:
                    return res
                si=si  # don't consume
                pi=ec+1; continue
            elif suffix==ord('*'):
                return self._max_expand(si, pi, ec)
            elif suffix==ord('+'):
                # 1 or more: start at si+1 then max_expand from there
                return self._max_expand(si+1, pi, ec)
            elif suffix==ord('-'):
                return self._min_expand(si, pi, ec)
            else:
                si+=1; pi=ec; continue

    def find_from(self, start):
        # return (start_index0, end_index0_inclusive? or end exclusive, captures list)
        # anchor?
        p=self.p
        anchored=False
        pi0=0
        if p[:1]==b'^':
            anchored=True; pi0=1
            # need create matcher with pattern chopped? _match uses self.p indexes. Instead self.p keep, _match called with pi=1, but class_end etc still works. But $ handling checks pi == len-1 okay.
        si=start
        while si<=self.slen:
            self.captures=[]
            try:
                res=self._start_match(si, pi0)
            except PatternError:
                raise
            if res is not None:
                caps=[]
