                    if cap['len']==-1:
                        raise PatternError(b"unfinished capture")
                    if cap['len']==-2:
                        caps.append(float(cap['start']+1))
                    else:
                        caps.append(self.s[cap['start']:cap['start']+cap['len']])
                return (si, res, caps)  # start 0-based, end exclusive
            if anchored:
                break
            si+=1
        return None
    def _start_match(self, si, pi0):
        return self._match(si, pi0)

def lua_pattern_find(s, p, init=1, plain=False):
    # return tuple or None; raises PatternError
    # init 1-based can neg
    n=len(s)
    if init<0:
        init=max(1, n+init+1)
    elif init==0:
        init=1
    if init>n+1:
        return None
    start=init-1
    if plain:
        idx=s.find(p, start)
        if idx==-1: return None
        return (idx, idx+len(p), [])
    m=Matcher(s,p)
    return m.find_from(start)

