    def __init__(self,pyfile,name=None,mode=b"r",is_popen=False,popen_obj=None,is_std=None):
        self.pyfile=pyfile; self.name=name; self.mode=mode; self.closed=False; self.is_popen=is_popen; self.popen_obj=popen_obj; self.is_std=is_std; self.close_at_eof_owner=False

def make_file_userdata(state, pyfile, name=None, mode=b"r", is_popen=False, popen_obj=None, is_std=None):
    ud=UserData(data=LuaFileData(pyfile,name,mode,is_popen,popen_obj,is_std))
    ud.metatable=state.file_metatable
    return ud
def check_file(state,args,i):
    v=arg_or(args,i,NOVALUE)
    if v is NOVALUE:
        # lua file methods usually self missing: bad argument #1 to '(name)' (FILE* expected, got no value)
        # custom type name FILE*
        state.arg_error(i+1,b"FILE* expected, got no value")
    if isinstance(v,UserData) and isinstance(v.data,LuaFileData):
        return v
    # type error: expected FILE* got <type> (luaL_checkudata message uses given type name)
    state.arg_error(i+1,b"FILE* expected, got "+lua_type(v))
