def _io_fileresult_error(state, filename_bytes, err: OSError):
    msg=err.strerror or str(err)
    if filename_bytes:
        return [None, filename_bytes+b": "+msg.encode(), float(err.errno or 0)]
    return [None,msg.encode(),float(err.errno or 0)]

def io_open(state,args,frame):
    fname=check_string(state,args,0)
    mode_str=opt_string(state,args,1,b"r")
    # Convert Lua mode to Python mode: remove b, ensure binary
    m=mode_str.decode('ascii','ignore')
    # Validate characters like C fopen: must start r w a + etc; Python may reject. If mode has other letters (e.g. "z") fopen returns EINVAL nil "Invalid argument"
    # Python open mode map
    # Must accept forms "r","rb","r+b","wb","a" etc; strip b then add b
    core=m.replace('b','').replace('t','')
    if core not in ('r','w','a','r+','w+','a+','x','x+'):
        # Invalid argument: Lua open may check mode and error argument? lua io.open invalid mode does luaL_argerror "(invalid format)"? Quick probe needed later.
        # Use fileresult nil Invalid argument
        import errno
        e=OSError(errno.EINVAL,"Invalid argument")
        return _io_fileresult_error(state,fname,e)
    pymode=core+'b'
    try:
        pyfile=open(fname.decode('utf-8','surrogateescape'),pymode)
    except OSError as e:
        return _io_fileresult_error(state,fname,e)
    return [make_file_userdata(state,pyfile,fname,mode_str)]
def io_tmpfile(state,args,frame):
