    return [make_file_userdata(state,pyfile,None,b"w+")]
def io_popen(state,args,frame):
    cmd=check_string(state,args,0)
    mode=opt_string(state,args,1,b"r")
    # validate mode only r w (maybe rb)
    mm=mode.replace(b'b',b'').replace(b't',b'')
    if mm not in (b"r",b"w"):
        # C popen invalid mode returns ? Lua io.popen checks mode and may argerror invalid format? Approximate fileresult EINVAL maybe no filename.
        return [None,b"Invalid argument",22.0]
    try:
        if mm==b"r":
            proc=subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=sys.stderr.buffer, stdin=subprocess.DEVNULL)
            pyfile=proc.stdout
        else:
            proc=subprocess.Popen(cmd, shell=True, stdin=subprocess.PIPE, stdout=sys.stdout.buffer, stderr=sys.stderr.buffer)
            pyfile=proc.stdin
    except Exception as e:
        return [None,str(e).encode(),0.0]
    return [make_file_userdata(state,pyfile,cmd,mode,is_popen=True,popen_obj=proc)]

def _file_close_internal(fd):
    # returns status for popen? or True
    if fd.closed:
        return True
    fd.closed=True
    try:
        if fd.is_std:
            # Flush std file but don't actually close underlying? fclose would close; emulate by flushing.
            try: fd.pyfile.flush()
            except: pass
            return True
        if fd.is_popen:
            if fd.pyfile:
                try: fd.pyfile.close()
                except: pass
            code=fd.popen_obj.wait()
            return code # modified by caller
        fd.pyfile.close()
        return True
    except Exception:
        return True

