    else:
        # seekable assumption
        pos=pyfile.tell(); data=pyfile.read(1024); pyfile.seek(pos)
        consumed_via_read=lambda n: pyfile.seek(pos+n)
    while skipped<len(data) and data[skipped] in b" \t\n\r\v\f":
        skipped+=1
