        consumed_via_read(skipped)
        return None
    rest=data[skipped:]
    # C double parse pattern including inf? skip
    import re as _re
    m=_re.match(rb"[+-]?(\d+\.?\d*([eE][+-]?\d+)?|\.\d+([eE][+-]?\d+)?|0[xX][0-9a-fA-F]+\.?[0-9a-fA-F]*([pP][+-]?\d+)?)",rest)
    if not m:
        # On failure, after skipping spaces, C fscanf leaves first non-number char unread? Lua read_number: uses fscanf and returns nil; it skips spaces via pattern (first reads spaces?) It probably consumed spaces only. Implement consume skipped.
        consumed_via_read(skipped)
        return None
    token=m.group(0)
    consumed_via_read(skipped+len(token))
    n=str_to_number(token)
    return n

