def file_seek_method(state,args,frame):
    ud=get_file_checked(state,args,0); fd=ud.data
    whence=opt_string(state,args,1,b"cur")
    offset=opt_int(state,args,2,0)
    whence_map={b"set":os.SEEK_SET,b"cur":os.SEEK_CUR,b"end":os.SEEK_END}
    if whence not in whence_map:
        state.arg_error(2,b"invalid option '"+whence+b"'")
    try:
        fd.pyfile.flush()
        fd.pyfile.seek(offset,whence_map[whence])
        pos=fd.pyfile.tell()
        return [float(pos)]
    except OSError as e:
        msg=e.strerror or str(e)
        return [None,msg.encode(),float(e.errno or 0)]
