def _io_file_change(state,args,which):
    current=state.io_default_input if which=='input' else state.io_default_output
    if not args or args[0] is None:
        return [current]
    a=args[0]
    if isinstance(a,UserData) and isinstance(a.data,LuaFileData):
        # Check closed? Lua io.input(FILE* closed) errors attempt use closed file
        if a.data.closed:
            state.arg_error(1,b"attempt to use a closed file")
        new=a
    else:
        fname=check_string(state,args,0)
        mode=b"r" if which=='input' else b"w"
        res=io_open(state,[fname,mode],None)
        if res[0] is None:
            # error raised as luaL_error with message provided (fname: msg)
            raise LuaError(res[1])
        new=res[0]
    if which=='input':
        state.io_default_input=new
    else:
        state.io_default_output=new
    return [new]

