def get_thread_arg(state,args):
    # helpers for debug functions where first arg optional thread
    if args and isinstance(args[0],LuaThread):
        return args[0],1
    return state.current_thread(),0

def frame_snapshot_for(state, thr):
    # If debugging current thread, live stack; if other coroutine, its stack list (may be preserved in thread.stack while suspended/dead? Our frame stack objects pop on yield? Cornoutine thread stack still has frames while suspended because python thread blocked inside calls, frames are on co.stack. When dead stack empty.)
