def get_frame_by_level(state, thr, level, caller_frame):
    # level interpretation for functions called from builtin debug.xxx: level 0 is debug function itself if current thread; level1 caller etc.
    # For external thread stack, level 0 is topmost function in that thread (i.e., no debug builtin frame in that stack)
    stack=frame_snapshot_for(state,thr)
    if thr is state.current_thread():
        idx=len(stack)-1-level
        if idx<0 or idx>=len(stack):
            return None
        return stack[idx]
    else:
        idx=len(stack)-1-level
        if idx<0 or idx>=len(stack):
            return None
        return stack[idx]

def info_for_function(state, func, fr=None, what_opts=b""):
