def free_vars_block(block, bound):
    # returns ordered list of names referenced but not in bound, applying local scopes within block AST approximate.
    # This is imperfect for scopes because AST plain but we can traverse statements in order maintaining scope sets.
    # We'll implement traversal with explicit scope stack recursion functions returning ordered unique list encountered.
    out=[]
    def add_name(nm, scope):
        if nm not in scope and nm not in out:
            out.append(nm)
    def visit_expr(e, scope):
        if e is None:
            return
        kind=e[0]
        if kind=='var':
            add_name(e[2], scope)
        elif kind in ('number','string','nil','bool','vararg','cdata_num'):
            return
        elif kind=='paren':
            visit_expr(e[2],scope)
        elif kind=='function':
            subproto=e[2]
