            # We compute child's free vars relative its params then add those not in scope
            child_free=free_vars_block(subproto.body, set(subproto.params))
            for nm in child_free:
                add_name(nm, scope)
        elif kind=='table':
            for field in e[2]:
                for sub in field[2:]:
                    # fields tuples: key expr val expr etc; namekey field[2] is name bytes
                    if isinstance(sub,tuple):
                        visit_expr(sub,scope)
        elif kind=='index':
            visit_expr(e[2],scope); visit_expr(e[3],scope)
        elif kind=='call':
            visit_expr(e[2],scope)
            for a in e[3]: visit_expr(a,scope)
        elif kind=='methodcall':
            visit_expr(e[2],scope)
            for a in e[4]: visit_expr(a,scope)
        elif kind=='unop':
            visit_expr(e[3],scope)
        elif kind=='binop':
            visit_expr(e[3],scope); visit_expr(e[4],scope)
        else:
            # generic walk tuples
            for item in e[2:]:
                if isinstance(item,tuple): visit_expr(item,scope)
                elif isinstance(item,list):
                    for it in item:
                        if isinstance(it,tuple): visit_expr(it,scope)
    def visit_block(blk, scope):
        scope=set(scope)
        for stmt in blk[2]:
            visit_stmt(stmt, scope)
    def visit_stmt(stmt, scope):
        kind=stmt[0]
        if kind=='do':
            visit_block(stmt[2], scope)
        elif kind=='while':
            visit_expr(stmt[2],scope); visit_block(stmt[3],scope)
        elif kind=='repeat':
            # body block scope then condition in body scope: approximate process body block and collect locals declared within body? Simplify visit block (which creates its own scope) and visit condition in same scope (overestimate could include locals as free? condition vars that are body local will be considered free if not included in scope). For a variable declared in repeat body used in until, analyzer should not mark as upvalue if it's body local of this same function. Our simple could overinclude. Approx: collect all local names declared directly in body block statements first then visit condition with that.
            body_locals=set(scope)
