        elif kind=='if':
            for cond,blk,line in stmt[2]:
                visit_expr(cond,scope); visit_block(blk,scope)
            if stmt[3]: visit_block(stmt[3],scope)
        elif kind=='fornum':
            visit_expr(stmt[3],scope); visit_expr(stmt[4],scope)
            if stmt[5]: visit_expr(stmt[5],scope)
            visit_block(stmt[6], scope|{stmt[2]})
        elif kind=='forgen':
            for e in stmt[3]: visit_expr(e,scope)
            visit_block(stmt[4], scope|set(stmt[2]))
        elif kind=='local':
            for e in stmt[3]: visit_expr(e,scope)
            scope.update(stmt[2])
        elif kind=='localfunc':
            scope.add(stmt[2])
            visit_expr(stmt[3],scope)
        elif kind=='assign':
            for tgt in stmt[2]: visit_expr(tgt,scope)
            for e in stmt[3]: visit_expr(e,scope)
        elif kind=='callstmt':
            visit_expr(stmt[2],scope)
        elif kind=='return':
            for e in stmt[2]: visit_expr(e,scope)
        elif kind in ('break','label','goto'):
            pass
        else:
            pass
    visit_block(block, set(bound))
    return out

