# Serializer
def enc_u(n):
    # prefix-encoded 32-bit unsigned n as spec: if n <0xe0 1 byte; elif n <0x1fe0 (?) range: 0x1fe0 threshold: .U grammar:
    # 0x00..0xdf -> n.B
    # 0xe0..0x1fdf -> bytes ((0xe0|(((n-0xe0)>>8)&0x1f)), ((n-0xe0)&0xff))
    # 0x1fe0.. -> 0xff n.I
    if n < 0xe0:
        return bytes([n])
    if n < 0x1fe0: # careful max: n-0xe0 <=0x1eff? formula yields first byte up to? Spec says range 0xe0...0x1fdf encodes dual byte - inconsistent because first byte only 0xe0-0xff with 0x1f mask and second byte gives max 0xe0+0x1fff=0x20df? Wait spec line: 0xe0..0x1fdf -> ... It might mean encoded byte representations values? Let's reason: Encode function lj_buf_putu: if x < 0xe0 put byte; elif x < 0x2000-0xe0? Need decode rationale: First byte 0xe0..0xfe carries high 5 bits (0..0x1e) and low byte; max x =0xe0+0x1efe? 0x1fe0? If first byte 0xff is special marker for 32-bit. So high bits allowed 0..0x1e (first byte <=0xfe). That means x-0xe0 <=0x1eff (if last byte ff) => x<=0x1fdf. Exactly spec says up to 0x1fdf. If x=0x1fe0 would require high 0x1f -> first byte 0xff conflict marker. So cutoff 0x1fe0 is next. Our condition n<0x1fe0 covers upto 0x1fdf.
        x=n-0xe0
        return bytes([0xe0 | ((x>>8)&0x1f), x & 0xff])
    return b"\xff"+struct.pack('<I', n & 0xffffffff)

class DecodeReader:
    def __init__(self,data,pos=0):
        self.data=data; self.pos=pos
    def need(self,n):
        if self.pos+n>len(self.data):
            raise LuaError(b"unexpected end of buffer")
    def byte(self):
        self.need(1); b=self.data[self.pos]; self.pos+=1; return b
    def bytes(self,n):
        self.need(n); b=self.data[self.pos:self.pos+n]; self.pos+=n; return bytes(b)
    def u32le(self):
        return struct.unpack('<I',self.bytes(4))[0]
    def i32le(self):
        return struct.unpack('<i',self.bytes(4))[0]
    def u64le(self):
        return struct.unpack('<Q',self.bytes(8))[0]
    def i64le(self):
        return struct.unpack('<q',self.bytes(8))[0]
    def f64(self):
        return struct.unpack('<d',self.bytes(8))[0]
    def u(self):
        b=self.byte()
        if b<0xe0:
            return b
        if b<0xff:
            b2=self.byte()
            return 0xe0 + ((b & 0x1f)<<8) + b2
        return self.u32le()

def encode_object(state, bd_opts, obj, depth=1, seen=None):
    # bd_opts BufferData or None for dict/mt mappings. Depth limit? Too deep error after? Original encoding recursion uses check depth LJ_SERIALIZATION_DEPTH=100? Circular triggers "too deep to serialize". We set maxDepth 100 maybe probe.
    if depth>100:  # approximate
        raise LuaError(b"too deep to serialize")
    if obj is None: return b"\x00"
    if obj is False: return b"\x01"
    if obj is True: return b"\x02"
    if type(obj) is float or type(obj) is int:
        return b"\x07"+struct.pack('<d',float(obj))
