            cv=obj.value
            return b"\x12"+struct.pack('<d',cv.real)+struct.pack('<d',cv.imag)
        # NULL pointer cdata maybe null code 3 if pointer null and handler says.
        if state.cdata_index_handler:
            # ask handler to serialize? It may return bytes or None
            try:
                r=state.cdata_index_handler('serialize',obj)
                if r is not None: return r
            except LuaError:
                raise
            except Exception:
                pass
        raise LuaError(b"cannot serialize 'cdata'")
