                    out+=encode_object(state,bd_opts,k,depth+1); out+=encode_object(state,bd_opts,v,depth+1)
                return out
        if a1>0:
            array_keys=set(float(i) for i in range(1,a1+1))
            hash_items=[(k,v) for (k,v) in obj.d.values() if not (type(k) is float and k in array_keys)]
