                return out
            else:
                out=prefix+b"\x0d"+enc_u(a1+1)+enc_u(len(hash_items))
                for i in range(1,a1+1):
                    out+=encode_object(state,bd_opts,obj.rawget(float(i)),depth+1)
                for k,v in hash_items:
