def decode_object(state,bd_opts,reader, depth=1):
    if depth>100:
        raise LuaError(b"buffer decode error: too deep") # message unknown for malformed nested typecodes leading deep; original may say "too deep to deserialize"? Probe later.
    # Important: Type codes above 0x12 and below? String encoding first byte is U-encoded 0x20+len not a single byte necessarily. Decoder must peek: The first numeral is read as U? Spec entails stream parser reads a U value `tag` first: values 0x00..0x1f are type codes, >=0x20 means string with length tag-0x20.
    tag=reader.u()
    if tag>=0x20:
        length=tag-0x20
        return reader.bytes(length)
    if tag==0x00: return None
    if tag==0x01: return False
    if tag==0x02: return True
    if tag==0x03:
        # null lightuserdata / ffi null pointer; if FFI loaded maybe returns cdata null, else? Serializer spec says null lightud. Decoding into Lua object outside ffi maybe returns light userdata NULL (?) Our VM doesn't have light userdata; return a UserData representing NULL (?) printing (?) Tests probably not.
        ud=UserData(data={'lightud':0})
        return ud
    if tag==0x04:
        val=reader.u32le(); return UserData(data={'lightud':val})
    if tag==0x05:
        val=reader.u64le(); return UserData(data={'lightud':val})
    if tag==0x06:
        return float(reader.i32le())
    if tag==0x07:
        return float(reader.f64())
    if tag==0x08:
        return LuaTable()
    if tag==0x09:
        h=reader.u(); t=LuaTable()
        for i in range(h):
            k=decode_object(state,bd_opts,reader,depth+1); v=decode_object(state,bd_opts,reader,depth+1)
            # Rawset nil key errors in malformed; original decoder malformed handling maybe errors "buffer decode error..."? We'll turn raw errors into generic.
            try: t.rawset(k,v)
            except LuaError as e: raise LuaError(b"invalid key in buffer") # placeholder
        return t
    if tag==0x0a:
        a=reader.u(); t=LuaTable()
        for i in range(a):
            v=decode_object(state,bd_opts,reader,depth+1); t.rawset(float(i),v)
        return t
    if tag==0x0b:
        a=reader.u(); h=reader.u(); t=LuaTable()
        for i in range(a):
            v=decode_object(state,bd_opts,reader,depth+1); t.rawset(float(i),v)
        for i in range(h):
            k=decode_object(state,bd_opts,reader,depth+1); v=decode_object(state,bd_opts,reader,depth+1); t.rawset(k,v)
        return t
    if tag==0x0c:
        a=reader.u(); t=LuaTable()
        for i in range(1,a): # (a-1) values for keys 1..
            v=decode_object(state,bd_opts,reader,depth+1); t.rawset(float(i),v)
        return t
    if tag==0x0d:
        a=reader.u(); h=reader.u(); t=LuaTable()
        for i in range(1,a):
            v=decode_object(state,bd_opts,reader,depth+1); t.rawset(float(i),v)
        for i in range(h):
            k=decode_object(state,bd_opts,reader,depth+1); v=decode_object(state,bd_opts,reader,depth+1); t.rawset(k,v)
        return t
    if tag==0x0e:
        idx=reader.u()+1 # metatable dict entry
        # following must be tab encoding
        t=decode_object(state,bd_opts,reader,depth+1)
        if not isinstance(t,LuaTable):
            raise LuaError(b"invalid buffer format") # placeholder
        # get mt
        mt=None
        if bd_opts and bd_opts.metatable_table:
            mt=bd_opts.metatable_table.rawget(float(idx))
            if mt is False:
                raise LuaError(b"cannot deserialize metatable") # unknown
            if isinstance(mt,LuaTable):
                t.metatable=mt
            else:
                raise LuaError(b"cannot deserialize metatable")
        else:
            # No dict configured: original error? Probably attempt decode metatable entry without a configured dict gives error "buffer decode error: ..."? We'll ignore metatable.
            pass
        return t
    if tag==0x0f:
        idx=reader.u()+1
        if bd_opts and bd_opts.dict_table:
            s=bd_opts.dict_table.rawget(float(idx))
            if type(s) is bytes:
                return s
            raise LuaError(b"cannot deserialize string") # unknown
        else:
            raise LuaError(b"cannot deserialize string") # unknown
    if tag==0x10:
        return CData(b"int64_t", reader.i64le())
    if tag==0x11:
        return CData(b"uint64_t", reader.u64le())
    if tag==0x12:
        re=reader.f64(); im=reader.f64(); return CData(b"complex", complex(re,im))
    # invalid tags 0x13-0x1f
    raise LuaError(b"invalid buffer format") # placeholder message probe later

def buf_encode_method(state,args,frame):
    buf=check_buffer(state,args,0)
    obj=args[1] if len(args)>1 else None
    # Encoding error handling: If error occurs mid-encoding, original may leave buffer partially appended? Encoder writes directly to buffer. Our encoder builds bytes fully then appends; on error no append. Edge.
    data=encode_object(state,buf.data,obj)
    buf.data.append(data)
    return [buf]
def buf_decode_method(state,args,frame):
    buf=check_buffer(state,args,0); bd=buf.data
    reader=DecodeReader(bytes(bd.data), bd.pos)
    # Bytes copy of whole data; reader pos initial offset.
    obj=decode_object(state,bd,reader)
    bd.pos=reader.pos
    if bd.pos==len(bd.data):
        bd.data=bytearray(); bd.pos=0
    return [obj]
def buffer_encode_func(state,args,frame):
    obj=args[0] if args else None
    data=encode_object(state,None,obj)
    return [data]
def buffer_decode_func(state,args,frame):
    s=check_string(state,args,0)
    reader=DecodeReader(s,0)
    obj=decode_object(state,None,reader)
    if reader.pos!=len(s):
        raise LuaError(b"left-over data in buffer")
    return [obj]

def register_buffer(state):
    # metatable
    mt=LuaTable()
    state.buffer_metatable=mt
    def B(name,fn,no): return BuiltinFunction(name,fn,no)
    # Methods table is itself metatable
    mt.rawset(b"__index",mt)
    mt.rawset(b"__metatable",b"buffer")
    mt.rawset(b"free",B(b"free",buf_free,204))
    mt.rawset(b"reset",B(b"reset",buf_reset,205))
    mt.rawset(b"skip",B(b"skip",buf_skip,206))
    mt.rawset(b"set",B(b"set",buf_set,207))
    mt.rawset(b"put",B(b"put",buf_put,208))
    mt.rawset(b"putf",B(b"putf",buf_putf,209))
    mt.rawset(b"get",B(b"get",buf_get,210))
    mt.rawset(b"putcdata",B(b"putcdata",buf_putcdata,211))
    mt.rawset(b"reserve",B(b"reserve",buf_reserve,212))
    mt.rawset(b"commit",B(b"commit",buf_commit,213))
    mt.rawset(b"ref",B(b"ref",buf_ref,214))
    mt.rawset(b"encode",B(b"encode",buf_encode_method,215))
    mt.rawset(b"decode",B(b"decode",buf_decode_method,216))
    mt.rawset(b"__gc",B(b"__gc",buf_gc,217))
    tostr=B(b"tostring",buf_tostring,218)
    mt.rawset(b"tostring",tostr)
    mt.rawset(b"__tostring",tostr)
    mt.rawset(b"__len",B(b"__len",buf_len,219))
