def sizeof_ct(ffi,ct):
    if ct is None: return None
    k=ct.kind
    if k=='void' or k=='function': return None
    if k=='pointer': return 8
    if k=='array':
        if ct.length is None or ct.length=='?' or ct.length<0: return None
        es=sizeof_ct(ffi,ct.base)
