    if k=='complex': return alignof_ct(ffi,ct.base)
    if ct.ctypes_type: return ctypes.alignment(ct.ctypes_type)
    return None

def to_ctypes(ffi,ct):
    if ct.ctypes_type is not None:
        return ct.ctypes_type
    k=ct.kind
    if k=='pointer':
        if ct.base.kind=='void': res=ctypes.c_void_p
        elif ct.base.kind=='function': res=to_ctypes(ffi,ct.base)
        else: res=ctypes.POINTER(to_ctypes(ffi,ct.base))
        ct.ctypes_type=res; return res
    if k=='array':
        if ct.length is None or ct.length=='?' or ct.length<0:
            raise LuaError(b"incomplete C type")
        res=to_ctypes(ffi,ct.base)*ct.length; ct.ctypes_type=res; return res
    if k=='enum':
        ct.ctypes_type=ctypes.c_int; return ctypes.c_int
    if k=='complex':
        elem=to_ctypes(ffi,ct.base)
        class Cx(ctypes.Structure):
            _fields_=[('re',elem),('im',elem)]
        ct.ctypes_type=Cx; return Cx
    if k in ('struct','union'):
        if ct.incomplete:
            raise LuaError(b"incomplete C type")
        # Create empty class first for recursion
        Base=ctypes.Structure if k=='struct' else ctypes.Union
        clsname=(ct.name or ('anon'+str(ct.id)))
        cls=type(str(clsname),(Base,),{})
        ct.ctypes_type=cls
        fields=[]; anon=[]
        for f in ct.fields:
            fname=f.name.decode('utf-8','surrogateescape') if f.name else ('_anon%d'%len(anon))
            if f.name is None: anon.append(fname)
            ft=to_ctypes(ffi,f.type) if not (f.type.kind=='array' and f.type.length=='?') else (to_ctypes(ffi,f.type.base)*0)
            if f.bitfield is not None:
                fields.append((fname,ft,f.bitfield))
            else:
                fields.append((fname,ft))
        if ct.pack is not None:
            cls._pack_=ct.pack
        if anon: cls._anonymous_=anon
        cls._fields_=fields
        return cls
    if k=='function':
        restype=None if ct.rettype.kind=='void' else to_ctypes(ffi,ct.rettype)
        argtypes=[]
        for a in ct.argtypes:
            argtypes.append(to_ctypes(ffi,a))
        res=ctypes.CFUNCTYPE(restype,*argtypes)
        ct.ctypes_type=res; return res
    if k=='void': return None
    raise LuaError(b"invalid C type")

def make_concrete_struct(ffi,ct,nelem):
    """For VLS, create a struct type copy where last array length=nelem; returns ctypes class and total size"""
    # Build a new CType struct copy
    fields=[]
    for f in ct.fields[:-1]: fields.append(f)
    last=ct.fields[-1]
    newarr=ffi.array_type(last.type.base, nelem)
    fields.append(CField(last.name,newarr,last.bitfield))
    copy=CType(ct.kind,name=ct.name,fields=fields)
    copy.pack=ct.pack; copy.id=ct.id; copy.metatable=ct.metatable
    return copy

def type_display(ffi,ct):
    if ct is None: return b"?"
    if isinstance(ct,(bytes,str)):
        return ct if isinstance(ct,bytes) else ct.encode()
    if ct.display_override: return ct.display_override
    k=ct.kind
    if k=='pointer':
        if ct.base.kind=='function':
            return type_display(ffi,ct.base.rettype)+b" (*)()"
        if ct.base.kind=='array':
            return type_display(ffi,ct.base)+b" *" # approximate
        return type_display(ffi,ct.base)+b" *"
    if k=='array':
        l=ct.length
        suf=b"[?]" if l=='?' else (b"[]" if l is None or l<0 else b"["+str(l).encode()+b"]")
        # LuaJIT display adds space: int [10]
        return type_display(ffi,ct.base)+b" "+suf
    if k=='function':
        return type_display(ffi,ct.rettype)+b" ()"
    if k in ('struct','union','enum'):
        if ct.name:
            return k.encode()+b" "+ct.name.encode() if isinstance(ct.name,str) else k.encode()+b" "+ct.name
        return k.encode()+b" "+str(ct.id).encode()
    if k=='complex': return b"complex" if ct.base.display_override==b"double" else b"complex float"
    if ct.name: return ct.name.encode() if isinstance(ct.name,str) else ct.name
    return k.encode()

