class CParseError(Exception):
    def __init__(self,msg): self.msg=msg

TOKEN_RE=re.compile(r"""\s*(?:(//[^\n]*)|(/\*.*?\*/)|\s+)""",re.S)
# Tokenizer manual
class CToken:
    __slots__=('kind','text')
    def __init__(self,k,t): self.kind=k; self.text=t
    def __repr__(self): return f"CToken({self.kind},{self.text!r})"

def tokenize_c(s):
    # s bytes decode latin1 for token text simplicity preserving byte values as unicode codepoints
    text=s.decode('latin1')
    toks=[]; i=0; n=len(text)
    while i<n:
        c=text[i]
        if c.isspace(): i+=1; continue
        if text.startswith('//',i):
            j=text.find('\n',i); i=n if j==-1 else j+1; continue
        if text.startswith('/*',i):
            j=text.find('*/',i+2)
            if j==-1: raise CParseError(b"missing end of comment")
            i=j+2; continue
        if c=='#' :
            # preprocessor line; capture pragma pack as token sequence? emit a special token with whole line
            j=text.find('\n',i); line=text[i:j if j!=-1 else n]; toks.append(CToken('pragma',line)); i=j if j!=-1 else n; continue
        if c.isalpha() or c=='_' or c=='$':
            j=i+1
            while j<n and (text[j].isalnum() or text[j] in '_$'): j+=1
            toks.append(CToken('id',text[i:j])); i=j; continue
        if c.isdigit() or (c=='.' and i+1<n and text[i+1].isdigit()):
            j=i
            # consume number-ish including suffixes and dots/exponents signs following e/p
            while j<n:
                ch=text[j]
                if ch.isalnum() or ch=='.': j+=1
                elif ch in '+-' and j>i and text[j-1] in 'eEpP': j+=1
                else: break
            toks.append(CToken('num',text[i:j])); i=j; continue
        if c=='"' or c=="'":
            quote=c; j=i+1; buf=[]
            while j<n:
                if text[j]=='\\' and j+1<n: buf.append(text[j:j+2]); j+=2; continue
                if text[j]==quote: j+=1; break
                buf.append(text[j]); j+=1
            toks.append(CToken('str' if quote=='"' else 'char', text[i:j])); i=j; continue
        if text.startswith('...',i): toks.append(CToken('punct','...')); i+=3; continue
        two=text[i:i+2]
        if two in ('<<','>>','<=','>=','==','!=','&&','||','->','++','--'): toks.append(CToken('punct',two)); i+=2; continue
        toks.append(CToken('punct',c)); i+=1
    toks.append(CToken('eof',''))
    return toks

def eval_c_int_expr(ffi,toks):
    # toks list CToken without eof; evaluate simple integer expression
    # Convert to python expression sanitized
    vals=[]
    i=0
    def peek(): return toks[i] if i<len(toks) else CToken('eof','')
    # recursive descent
    def parse_expr():
        nonlocal i
        v=parse_term()
        while peek().text in ('|','^','&','<<','>>','+','-'):
            op=peek().text; i_inc()
            r=parse_term() if op in ('+','-') else parse_expr()
            if op=='+': v=v+r
            elif op=='-': v=v-r
            elif op=='|': v=v|r
            elif op=='^': v=v^r
            elif op=='&': v=v&r
            elif op=='<<': v=v<<r
            elif op=='>>': v=v>>r
        return v
    def i_inc():
        nonlocal i; i+=1
    def parse_term():
        nonlocal i
        v=parse_factor()
        while peek().text in ('*','/','%'):
            op=peek().text; i+=1; r=parse_factor()
            if op=='*': v=v*r
            elif op=='/': v=int(v/r) if r else 0
            elif op=='%': v=v%r if r else 0
        return v
    def parse_factor():
        nonlocal i
        t=peek()
        if t.text=='-': i+=1; return -parse_factor()
        if t.text=='+': i+=1; return parse_factor()
        if t.text=='~': i+=1; return ~parse_factor()
        if t.text=='!': i+=1; return 0 if parse_factor() else 1
        if t.text=='(':
            i+=1; v=parse_expr()
            if peek().text==')': i+=1
            return v
        if t.kind=='num':
            i+=1; return parse_c_number(t.text)
        if t.kind=='char':
            i+=1; return parse_c_char(t.text)
        if t.kind=='id':
            name=t.text.encode(); i+=1
            if name in ffi.constants:
                v=ffi.constants[name]; return int(v) if isinstance(v,(int,float)) else 0
            # sizeof etc not support
            return 0
        i+=1; return 0
    try:
        return parse_expr()
    except Exception:
        return 0

def parse_c_number(txt):
    t=txt.strip()
    # remove suffixes uUlL
    is_float=False
    low=t.lower()
    # hex float
    try:
        if low.startswith('0x'):
            core=t.rstrip('uUlL')
            if '.' in core or 'p' in core.lower():
                return float.fromhex(core[2:])
            return int(core,16)
        if low.startswith('0b'):
