        if '.' in t or 'e' in low:
            return float(t.rstrip('fFlL'))
        if len(t)>1 and t[0]=='0':
            # octal maybe
            core=t.rstrip('uUlL')
            try: return int(core,8)
            except: return int(core,10)
        return int(t.rstrip('uUlL'),10)
    except Exception:
        try: return float(t)
        except: return 0
def parse_c_char(txt):
    # txt includes quotes latin1
    if len(txt)<2: return 0
    inner=txt[1:-1]
    if not inner: return 0
    if inner[0]!='\\': return ord(inner[0])
    esc=inner[1:]
    mp={'n':10,'t':9,'r':13,'0':0,'a':7,'b':8,'f':12,'v':11,'\\':92,"'":39,'"':34,'?':63}
    if esc and esc[0] in mp: return mp[esc[0]]
    if esc and esc[0]=='x':
        try: return int(esc[1:],16)
        except: return 0
    if esc and esc[0].isdigit():
        try: return int(esc,8)
        except: return 0
    return ord(esc[0]) if esc else 0

