        i+=1
        if i>=len(body): break
        e=body[i]; i+=1
        mp={'n':10,'t':9,'r':13,'a':7,'b':8,'f':12,'v':11,'\\':92,'"':34,"'":39,'?':63}
        if e in mp: out.append(mp[e])
        elif e=='x':
