        if stack and stack[-1] is fr: stack.pop()
        elif fr in stack: stack.remove(fr)
    errs=getattr(state,'ffi_callback_errors',[]) or []
    if len(errs)>callback_error_count:
        # propagate first callback error
        raise errs[callback_error_count]
    return convert_c_return(ffi,functype.rettype,raw)

