def promote_numeric_result(ffi,op,a,b):
    # returns python result converted to Lua according FFI promotion or NotImplemented
    ea=extract_numeric(ffi,a); eb=extract_numeric(ffi,b)
    if ea is None or eb is None: return NotImplemented
    if ea[0]=='complex' or eb[0]=='complex': return NotImplemented
    # pointers handled elsewhere
    # Determine floating: if either is float typed cdata or Lua non-integral number? Lua numbers in FFI arithmetic: a Lua number operand is converted based on other: if other is integer cdata, operand converted to integer (trunc) if it is ??? Example int64 + 1.5 =>  ? It may convert to double if fractional. Simplify: if either extracted float from float ctype or Lua float that is not from integer cdata and (other isn't int64 with integral?) We need distinguish source types: extract loses. Determine from objects:
    def is_float_source(x):
        if type(x) is float: return not (math.isfinite(x) and x==int(x))  # integral Lua numbers may convert to int when other is int cdata; if both Lua handled by core before cdata branch. At least one cdata here.
        if isinstance(x,CData): return x.ctype.kind=='float'
        return False
    def int_type_info(x):
        if isinstance(x,CData):
            ct=x.ctype
            if ct.kind=='int': return (sizeof_ct(ffi,ct),ct.signed)
            if ct.kind in ('enum','bool'): return (4,True)
        return None
    if is_float_source(a) or is_float_source(b) or ea[0]=='float' and isinstance(a,CData) and a.ctype.kind=='float' or eb[0]=='float' and isinstance(b,CData) and b.ctype.kind=='float':
        x=float(ea[1]); y=float(eb[1])
        # Operation float result as Lua number (double) - FFI arithmetic on float cdata returns double Lua number? likely.
        if op==b"__add": return x+y
        if op==b"__sub": return x-y
        if op==b"__mul": return x*y
        if op==b"__div": return x/y if y!=0 else (math.inf if x!=0 else math.nan)
        if op==b"__mod": return x - math.floor(x/y)*y if y!=0 else math.nan
        if op==b"__pow":
            try: return math.pow(x,y)
            except Exception: return math.nan
        return NotImplemented
    # Integer arithmetic in 64bit
    x=int(ea[1]); y=int(eb[1])
    unsigned=False
    # unsigned if any operand is unsigned 64 OR (?) both/one unsigned 32? FFI promotion: If one operand is unsigned int64 -> uint64. If one is unsigned 32 and other signed 64 -> uint64. We'll promote if any int source unsigned and size==8 or (unsigned32 and other is int64). Simpler: if any source unsigned int type with size 8 -> unsigned; if any unsigned and neither signed 8? Result in LuaJIT for uint32+int32 might be int64 (signed) because values fit. Keep signed unless ea/eb marked unsigned64.
    unsigned = ea[2] or eb[2]
    if op==b"__unm":
        r=-x
    elif op==b"__add": r=x+y
    elif op==b"__sub": r=x-y
    elif op==b"__mul": r=x*y
    elif op==b"__div":
        if y==0: raise LuaError(b"division by zero")
        if unsigned: r=(x&((1<<64)-1))//(y&((1<<64)-1))
        else: r=(abs(x)//abs(y))*(1 if (x<0)==(y<0) else -1)
    elif op==b"__mod":
        if y==0: raise LuaError(b"division by zero")
        if unsigned: r=(x&((1<<64)-1))%(y&((1<<64)-1))
