                return make_pointer(ffi,pb.ctype,get_cdata_addr(ffi,pb)+n*es,pb.owner)
        return NotImplemented
    # Numeric cdata
    if (isinstance(a,CData) and a.ctype.kind in ('int','bool','enum','float','complex')) or (isinstance(b,CData) and b.ctype.kind in ('int','bool','enum','float','complex')):
