    ea=extract_numeric(ffi,a); eb=extract_numeric(ffi,b)
    if ea is None or eb is None: return NotImplemented
    if ea[0]=='complex' or eb[0]=='complex':
        if op==b"__eq": return ea[1]==eb[1] if ea[0]=='complex' and eb[0]=='complex' else False
        return NotImplemented
    # int vs float compare with exact int64 if both int-ish
    if ea[0]=='int' and eb[0]=='int':
        x=ea[1]; y=eb[1]
        if ea[2] or eb[2]: x&=((1<<64)-1); y&=((1<<64)-1)
