    if ct.kind=='enum':
        ex=extract_numeric(ffi,obj); return b"cdata<"+disp+b">: "+str(int(ex[1])).encode() if ex else b"cdata<"+disp+b">: 0"
    if ct.kind=='pointer':
        addr=get_cdata_addr(ffi,obj) or 0
        if addr==0: return b"cdata<"+disp+b">: NULL"
        return b"cdata<"+disp+b">: 0x"+format(addr,"x").encode()
    addr=get_cdata_addr(ffi,obj)
    if addr is None: addr=id(obj)
    return b"cdata<"+disp+b">: 0x"+format(addr,"x").encode()

