        cand=('lib' if not name_str.startswith('lib') else '')+name_str+'.so'
    mode=ctypes.RTLD_GLOBAL if global_flag else ctypes.RTLD_LOCAL
    try:
        lib=ctypes.CDLL(cand,mode=mode)
    except OSError as e:
        # message e.args[0] is like "libx.so: cannot open shared object..."
        msg=str(e)
        raise LuaError(msg.encode())
    ud=UserData(data=CLibData(name_b,lib,False))
    ud.metatable=state.clib_metatable
    return ud

