    ffi.rawset(b"typeinfo",B(b"typeinfo",ffi_typeinfo,191))
    ffi.rawset(b"istype",B(b"istype",ffi_istype,192))
    ffi.rawset(b"sizeof",B(b"sizeof",ffi_sizeof,193))
    ffi.rawset(b"alignof",B(b"alignof",ffi_alignof,194))
    ffi.rawset(b"offsetof",B(b"offsetof",ffi_offsetof,195))
    ffi.rawset(b"errno",B(b"errno",ffi_errno,196))
