def ffi_gc(state,args,frame):
    ffi=get_ffi(state); obj=args[0] if args else None
    if not isinstance(obj,CData): state.arg_error(1,b"cdata expected, got "+lua_type(obj))
    finalizer=args[1] if len(args)>1 else None
    if finalizer is None:
        obj.gc_finalizer=None; return [obj]
    # register deferred finalizer
    import weakref
    # Make a clone sharing memory/type for finalizer argument (see discussion)
    clone=CData(obj.ctype,obj.value); clone.addr=obj.addr; clone.owner=obj.owner; clone.ptr=obj.ptr
    # Remove old finalize if any
    old=getattr(obj,'gc_finalizer',None)
    if old is not None:
        try: old.detach()
        except Exception: pass
    def enqueue(clone=clone,finalizer=finalizer):
        if not hasattr(state,'gc_pending'): state.gc_pending=[]
        state.gc_pending.append((clone,finalizer))
    fin=weakref.finalize(obj,enqueue)
    fin.atexit=False
    obj.gc_finalizer=fin
    return [obj]
def ffi_metatype(state,args,frame):
