def load_library(ffi,name_b,global_flag=False):
    state=ffi.state
    name_str=name_b.decode('utf-8','surrogateescape')
    if '/' in name_str:
        cand=name_str
    elif '.' in name_str:
        cand=name_str
    else:
        cand=('lib' if not name_str.startswith('lib') else '')+name_str+'.so'
    mode=ctypes.RTLD_GLOBAL if global_flag else ctypes.RTLD_LOCAL
    try:
        lib=ctypes.CDLL(cand,mode=mode)
    except OSError as e:
        # message e.args[0] is like "libx.so: cannot open shared object..."
        msg=str(e)
        raise LuaError(msg.encode())
    ud=UserData(data=CLibData(name_b,lib,False))
    ud.metatable=state.clib_metatable
    return ud

def ffi_load(state,args,frame):
    ffi=get_ffi(state)
    name=check_string(state,args,0)
    glob=False
    if len(args)>=2 and args[1] is not None: glob=lua_truthy(args[1])
    return [load_library(ffi,name,glob)]

def resolve_default_lib(ffi):
    if ffi.default_lib is not None: return ffi.default_lib
    # Preload common libs global
    for libname in ('libc.so.6','libm.so.6','libdl.so.2','libpthread.so.0'):
        try: ctypes.CDLL(libname,mode=ctypes.RTLD_GLOBAL)
        except Exception: pass
    try:
        lib=ctypes.CDLL(None,mode=ctypes.RTLD_GLOBAL)
    except Exception:
        lib=ctypes.CDLL('libc.so.6',mode=ctypes.RTLD_GLOBAL)
    ffi.default_lib=lib
    return lib

def clib_index(state,args,frame):
    # __index metamethod function args (libuserdata, key)
    libud=args[0]; key=args[1]
    ffi=get_ffi(state)
    if type(key) is not bytes:
        return [None]
    # constants first
    if key in ffi.constants:
        return [ffi.constants[key]]
    symtype=ffi.symbols.get(key)
    if symtype is None:
        # Original error for ffi.C.missing - likely 'missing declaration for symbol'? We'll raise with where? Index operation from VM will show message as raised. Use plain.
        raise LuaError(b"missing declaration for symbol '"+key+b"'")
    clibdata=libud.data
    libobj=clibdata.lib
    if clibdata.is_default:
        libobj=resolve_default_lib(ffi)
    if symtype.kind=='function':
        # resolve symbol
        try:
            func=getattr(libobj,key.decode())
            addr=ctypes.cast(func,ctypes.c_void_p).value
        except Exception:
            raise LuaError(b"symbol '"+key+b"' not found")
        return [make_pointer(ffi,ffi.pointer_type(symtype),addr,libobj)]
    else:
        # global variable: get its address using c_void_p in_dll
        try:
            addr=ctypes.c_void_p.in_dll(libobj,key.decode()).value
        except Exception:
            raise LuaError(b"symbol '"+key+b"' not found")
        if symtype.kind=='array':
            return [make_ref(ffi,symtype,addr,libobj)]
        return [read_value_at(ffi,addr,symtype,libobj)]

def clib_newindex(state,args,frame):
    libud=args[0]; key=args[1]; val=args[2]
    ffi=get_ffi(state)
    if type(key) is not bytes: raise LuaError(b"cannot set library symbol")
    symtype=ffi.symbols.get(key)
    if symtype is None or symtype.kind=='function':
        raise LuaError(b"cannot write to symbol '"+key+b"'")
    clibdata=libud.data
    libobj=clibdata.lib
    if clibdata.is_default: libobj=resolve_default_lib(ffi)
    try: addr=ctypes.c_void_p.in_dll(libobj,key.decode()).value
    except Exception: raise LuaError(b"symbol '"+key+b"' not found")
    assign_to_addr(ffi,addr,symtype,val)
    return []

# Handler invoked by VM for cdata operations
def cdata_handler(state,action,*a):
    ffi=get_ffi(state)
    # action conventions from vm/buffer:
    # ('__metatable__', obj), ('index',obj,key), ('tobytes',obj,len), ('ptr_to_bytearray',arr,buf), ('ptr_to_buffer_ref',buf), ('serialize',obj), ('iscallable',obj), ('call',obj,args,name,line)
    if action=='__metatable__':
        obj=a[0]; return cdata_metatable(ffi,obj)
    if action=='index':
        return cdata_index(ffi,a[0],a[1])
    if action=='tobytes':
        obj=a[0]
        # obj may be bytearray pointer fallback
        if isinstance(obj,CData):
            addr=get_cdata_addr(ffi,obj); n=a[1] if len(a)>1 else 0; return ctypes.string_at(addr,n)
        return None
    if action=='serialize':
        # handled in buffer encode for int64/complex independently; null pointer:
        obj=a[0]
        if isinstance(obj,CData) and obj.ctype.kind=='pointer' and (get_cdata_addr(ffi,obj) or 0)==0:
            return b"\x03"
        return None
    if action=='ptr_to_bytearray':
        arr=a[0]
        # arr is ctypes buffer if bufferlib updated, or bytearray
        if isinstance(arr,bytearray):
            # create ctypes view sharing it
            view=(ctypes.c_char*len(arr)).from_buffer(arr) if len(arr) else ctypes.create_string_buffer(1)
            addr=ctypes.addressof(view) if len(arr) else ctypes.addressof(view)
            owner=view
        else:
            # ctypes buffer
            addr=ctypes.addressof(arr); owner=arr
        return make_pointer(ffi,ffi.pointer_type(ffi.prim('unsigned char')),addr,owner)
    if action=='ptr_to_buffer_ref':
        buf=a[0]; bd=buf.data
        remaining=bd.remaining()
        if remaining<=0:
            return make_pointer(ffi,ffi.pointer_type(ffi.prim('unsigned char')),0,buf)
        # compact buffer to simplify view offset0
        bd.discard_front()
        view=(ctypes.c_char*len(bd.data)).from_buffer(bd.data)
        addr=ctypes.addressof(view)
        return make_pointer(ffi,ffi.pointer_type(ffi.prim('unsigned char')),addr,view)
    if action=='iscallable':
        obj=a[0]
        if not isinstance(obj,CData): return False
        normalize_cdata(ffi,obj)
        if obj.ctype.kind=='ctype': return True
        if obj.ctype.kind=='function': return True
        if obj.ctype.kind=='pointer' and obj.ctype.base.kind=='function': return True
        return False
    if action=='call':
        obj=a[0]; call_args=a[1]; call_name=a[2] if len(a)>2 else None; line=a[3] if len(a)>3 else None
        normalize_cdata(ffi,obj)
        if obj.ctype.kind=='ctype':
            return [create_cdata(ffi,obj.value,call_args)]
        ft=None
        if obj.ctype.kind=='function': ft=obj.ctype
        elif obj.ctype.kind=='pointer' and obj.ctype.base.kind=='function': ft=obj.ctype.base
        if ft is not None:
            return call_c_function(ffi,obj,ft,call_args,call_name=call_name,line=line)
        return None
    return None

def cdata_newindex_handler(state,obj,key,value):
    ffi=get_ffi(state); return cdata_newindex(ffi,obj,key,value)

def register_ffi(state):
    ffi_state=FFIState(state)
    state.ffi_state=ffi_state
    ffi=LuaTable()
    # clib metatable
    clib_mt=LuaTable(); state.clib_metatable=clib_mt
    clib_mt.rawset(b"__index",BuiltinFunction(b"__index",clib_index,None))
    clib_mt.rawset(b"__newindex",BuiltinFunction(b"__newindex",clib_newindex,None))
    Cud=UserData(data=CLibData(b"C",None,True)); Cud.metatable=clib_mt
    ffi.rawset(b"C",Cud)
    def B(name,fn,no): return BuiltinFunction(name,fn,no)
    ffi.rawset(b"cdef",B(b"cdef",ffi_cdef,187))
    ffi.rawset(b"new",B(b"new",ffi_new,188))
    ffi.rawset(b"cast",B(b"cast",ffi_cast,189))
    ffi.rawset(b"typeof",B(b"typeof",ffi_typeof,190))
    ffi.rawset(b"typeinfo",B(b"typeinfo",ffi_typeinfo,191))
    ffi.rawset(b"istype",B(b"istype",ffi_istype,192))
    ffi.rawset(b"sizeof",B(b"sizeof",ffi_sizeof,193))
    ffi.rawset(b"alignof",B(b"alignof",ffi_alignof,194))
    ffi.rawset(b"offsetof",B(b"offsetof",ffi_offsetof,195))
    ffi.rawset(b"errno",B(b"errno",ffi_errno,196))
    ffi.rawset(b"string",B(b"string",ffi_string,197))
    ffi.rawset(b"copy",B(b"copy",ffi_copy,198))
    ffi.rawset(b"fill",B(b"fill",ffi_fill,199))
    ffi.rawset(b"abi",B(b"abi",ffi_abi,200))
    ffi.rawset(b"metatype",B(b"metatype",ffi_metatype,201))
    ffi.rawset(b"gc",B(b"gc",ffi_gc,202))
    ffi.rawset(b"load",B(b"load",ffi_load,203))
    ffi.rawset(b"os",b"Linux"); ffi.rawset(b"arch",b"x64")
    state.ffi_table=ffi; state.clib_C=Cud
    # VM handlers
    state.cdata_index_handler=lambda act,*a: cdata_handler(state,act,*a)
    state.cdata_newindex_handler=lambda obj,k,v: cdata_newindex_handler(state,obj,k,v)
    state.cdata_call_handler=lambda act,*a: cdata_handler(state,act,*a)
    state.cdata_tostring_handler=lambda obj: cdata_tostring(ffi_state,obj)
    state.cdata_arith_handler=lambda op,a,b: ffi_arith(ffi_state,op,a,b)
    state.cdata_len_handler=lambda obj: (float(obj.ctype.length) if isinstance(obj,CData) and getattr(obj.ctype,'kind',None)=='array' and isinstance(obj.ctype.length,int) else None)
    return ffi
